-- Biblioteka e madhe e përrallave, pjesa 2 nga 5 (22 përralla).
-- Përralla më të gjata (8–15 minuta lexim): popullore shqiptare, klasike të rrëfyera (Grim, Andersen, Ezopi, Peroi,
-- Kipling, Kolodi, Kerolli, Baumi e të tjera, të gjitha të lira nga e drejta e autorit) dhe përralla origjinale të Bebix-it.
-- Secila ka ilustrimin e vet (cover_svg, i kontrolluar me pastruesin e app-it) dhe dalin në app pa përditësim.
-- I sigurt për t'u ekzekutuar dy herë: përrallat që ekzistojnë (sipas slug) nuk preken. Nuk fshin asgjë.
-- Kërkon migrimet 20261024090000_stories.sql dhe 20261025090000_story_drafts.sql (kolona cover_svg, source).

insert into public.stories (slug, language, title, summary, paragraphs, categories, age_min_months, age_max_months, reading_minutes, cover_key, cover_svg, status, featured, sort_order, source)
values
(
  $s$muzikantet-e-bremenit$s$, 'sq', $s$Muzikantët e Bremenit$s$,
  $s$Sipas vëllezërve Grim: një gomar, një qen, një mace dhe një gjel, që s'i do më askush, nisen bashkë për t'u bërë muzikantë, dhe gjejnë diçka më të mirë se muzika.$s$,
  array[
    $s$Na ishte një herë një gomar, që kishte punuar shumë vjet në mulli, duke mbajtur thasë të rëndë me grurë. Por tani ishte plakur dhe forca po i lëshonte. I zoti filloi të mendonte se nuk i shërbente më. Gomari e kuptoi, dhe një mëngjes u nis vetë drejt qytetit të Bremenit. «Atje», mendoi, «mund të bëhem muzikant. Zërin e kam ende të fortë.»$s$,
    $s$Kishte ecur pak, kur gjeti në anë të rrugës një qen gjahu, të shtrirë e të lodhur, që gulçonte. «Pse gulçon kështu, mik?» e pyeti gomari. «Ah», tha qeni, «jam plakur, s'vrapoj më dot pas lepujve, dhe i zoti s'më do më. Ika, por s'di ku të shkoj.» «Eja me mua në Bremen», tha gomari. «Do të bëhemi muzikantë. Unë do t'i bie lahutës, ti do t'i biesh daulles.» Qeni u gëzua dhe u nis me të.$s$,
    $s$Pas pak, panë një mace të ulur në rrugë, me një fytyrë të trishtuar si tri ditë shi. «Ç'ke, mace e vjetër?» e pyeti gomari. «Kush mund të jetë i gëzuar kur i rrezikohet shtëpia?» tha maca. «Jam plakur, dhëmbët s'më mprehen më, dhe më pëlqen të rri pranë sobës më shumë se të ndjek minjtë. E zonja s'më do më.» «Eja me ne në Bremen», i thanë. «Ti di këngët e natës, do të bëhesh muzikante.» Dhe maca shkoi me ta.$s$,
    $s$Pastaj kaluan pranë një oborri, dhe mbi portë ishte një gjel që këndonte me gjithë fuqinë: kikirikiii! «Pse këndon kështu, sikur do të të çahet zemra?» e pyeti gomari. «Kam dëgjuar që nesër kanë miq», tha gjeli, «dhe e zonja do të bëjë supë. Dhe nuk dua të jem unë supa! Prandaj po këndoj sa kam frymë, sa ende mundem.» «Eja me ne, kokëkuqi», tha gomari. «Ke zë të fortë. Do të bëjmë muzikë së bashku.» Gjeli pranoi menjëherë, dhe të katër u nisën bashkë.$s$,
    $s$Bremeni ishte larg, dhe në mbrëmje arritën në një pyll. Gomari dhe qeni u shtrinë nën një pemë të madhe, maca u ngjit në një degë, dhe gjeli fluturoi deri në majë, sepse aty ndihej më i sigurt. Para se të flinte, gjeli vështroi përreth, dhe pa larg një dritë të vogël. «Atje ka një shtëpi», thirri. «Shkojmë, se këtu ka ftohtë dhe s'kemi ngrënë asgjë.»$s$,
    $s$U nisën drejt dritës, që bëhej gjithnjë e më e madhe, derisa arritën te një shtëpi e ndriçuar. Gomari, që ishte më i gjati, u afrua te dritarja dhe shikoi brenda. «Çfarë sheh, gomar?» e pyeti gjeli. «Shoh një tryezë plot me ushqime të mira», tha gomari, «dhe rreth saj janë ulur disa hajdutë, që po hanë e po pinë dhe po numërojnë florinjtë që kanë vjedhur.»$s$,
    $s$Kafshët u mblodhën të mendonin si t'i përzinin hajdutët. Më në fund gjetën një plan. Gomari vuri këmbët e përparme mbi dritare. Qeni u hodh mbi shpinën e gomarit. Maca u ngjit mbi shpinën e qenit. Dhe gjeli fluturoi dhe u ul mbi kokën e maces. Pastaj, me një shenjë, filluan të gjithë njëkohësisht muzikën e tyre.$s$,
    $s$Gomari pëlliti, qeni lehu, maca mjaulliu dhe gjeli këndoi, dhe të gjithë bashkë ranë brenda nga dritarja, mes zhurmës së xhamave. Hajdutët u hodhën përpjetë nga frika. Menduan se kishte hyrë një përbindësh me katër koka dhe ikën me vrap në pyll, aq shpejt sa harruan edhe kapelet.$s$,
    $s$Katër miqtë u ulën rreth tryezës dhe hëngrën gjithçka që kishte mbetur, sikur të mos kishin ngrënë prej katër javësh. Pastaj fikën dritat dhe secili gjeti një vend për të fjetur: gomari në oborr mbi kashtë, qeni pas derës, maca pranë vatrës së ngrohtë dhe gjeli mbi trarin e çatisë. Dhe ishin aq të lodhur, sa i zuri gjumi menjëherë.$s$,
    $s$Pas mesnate, hajdutët panë nga larg që në shtëpi s'kishte më dritë. Kreu i tyre tha: «S'duhej të ishim trembur kaq shumë.» Dhe dërgoi njërin të shikonte. Hajduti hyri në shtëpinë e errët. Pa në vatër dy sy që shkëlqenin dhe mendoi se ishin dy thëngjij të ndezur. I afroi një shkrepse për të ndezur dritën.$s$,
    $s$Por ata nuk ishin thëngjij. Ishin sytë e maces. Maca u hodh dhe e gërvishti në fytyrë. Hajduti iku drejt derës, ku qeni i kafshoi lehtë këmbën. Kur kaloi në oborr, gomari i dha një shkelm. Dhe gjeli, që u zgjua nga zhurma, thirri nga trari: kikirikiii!$s$,
    $s$Hajduti u kthye me vrap te shokët e tij. «Në atë shtëpi», tha duke dridhur, «jeton një shtrigë që më gërvishti me thonj të gjatë. Te dera rri një burrë me thikë, që më shpoi këmbën. Në oborr është një përbindësh i zi, që më goditi me shkop. Dhe mbi çati rri gjykatësi, që bërtiste: Sillni hajdutin këtu!» Hajdutët u trembën aq shumë, sa s'u kthyen më kurrë.$s$,
    $s$Dhe katër muzikantët? Nuk arritën kurrë në Bremen. Shtëpia në pyll u pëlqeu aq shumë, sa mbetën aty, të katër bashkë. Kthyen florinjtë e vjedhur te njerëzit e fshatit, dhe çdo mbrëmje bënin muzikën e tyre, pak të çuditshme, por të gëzuar, për veten dhe për kafshët e pyllit. Sepse kishin kuptuar që nuk u duhej një qytet i madh. U duheshin vetëm njëri-tjetri.$s$
  ]::text[],
  array['classic', 'friendship']::text[], 36, 96, 11, null,
