(
  $s$drita-e-nates$s$, 'sq', $s$Drita e vogël e natës$s$,
  $s$Një dritë nate në formë hëne ka frikë nga errësira, deri sa kupton pse ekziston dhe sa e rëndësishme është për Benin e vogël.$s$,
  array[
    $s$Në dhomën e Benit, në prizën pranë shtratit, ishte një dritë e vogël nate. Kishte formën e një gjysmëhëne dhe ndriçonte me një dritë të verdhë, të butë, si mjaltë. Ishte e re: babai e kishte blerë atë ditë, se Beni kishte filluar të kishte frikë nga errësira.$s$,
    $s$Dritës së vogël të natës s'i kishte shpjeguar askush çfarë duhej të bënte. Gjithë ditën kishte qenë e fikur, duke parë dhomën: kubet në qilim, librat në raft, ariun e madh mbi karrige, perdet me retë. Dhe kur ra mbrëmja e babai e ndezi për herë të parë, drita e vogël u habit. Rreth saj, gjithçka ishte errësuar.$s$,
    $s$«Oh», tha drita e vogël me vete, «po bëhet errët. Shumë errët.» Shikoi përreth. Dollapi ishte bërë një hije e madhe. Palltoja e varur pas derës dukej si një gjigant. Dritarja ishte një katror i zi. «Kam frikë», mendoi drita e vogël. «Nuk më pëlqen errësira. Pse më kanë vënë këtu, në mes të errësirës?»$s$,
    $s$Pastaj Beni hyri në dhomë, me pizhama e me ariun e vogël në krah. U fut në shtrat dhe babai e mbuloi. «A do ta lëmë ndezur dritën e vogël?» pyeti babai. «Po», tha Beni. «Dhe nuk do të kesh frikë?» «Jo, se drita do të më ruajë.» Drita e vogël e dëgjoi dhe u habit shumë. «Unë? Do ta ruaj unë? Por unë vetë kam frikë!»$s$,
    $s$Babai i dha Benit një puthje dhe doli, duke e lënë derën pak të hapur. Dhoma u bë e heshtur. Beni ishte shtrirë me sytë hapur, duke parë dritën e vogël. Drita e vogël ishte e trembur, por u përpoq të ndriçonte sa më mirë që mundej. «Nëse Beni beson që unë e ruaj», mendoi, «duhet të përpiqem.»$s$,
    $s$Papritur, Beni u ngrit pak nga jastëku. «Çfarë është ajo?» pëshpëriti, duke treguar me gisht drejt derës. Atje, pas derës, ishte një hije e madhe, me krahë të gjatë e me kokë të çuditshme. Drita e vogël u drodh. Por pastaj, ndriçoi pak më fort, aq fort sa mundi, drejt hijes. Dhe hija u bë më e qartë. Nuk ishte përbindësh. Ishte palltoja e babait, e varur në grep, me kapelën e tij sipër.$s$,
    $s$«Ah», tha Beni, dhe buzëqeshi. «Është palltoja e babit.» Drita e vogël ndjeu diçka të ngrohtë brenda saj. «Pra», mendoi, «unë mund t'i bëj hijet të shohin se çfarë janë në të vërtetë.» Dhe kjo i dha pak guxim.$s$,
    $s$Pak më vonë, Beni pyeti përsëri: «Po ajo, në qoshe?» Në qoshe ishte një formë e rrumbullakët e madhe, si një kafshë e shtrirë. Drita e vogël ndriçoi atë anë. Ishte kosha e rrobave, me një peshqir të madh sipër. «Ah», tha Beni. «Është kosha.» Dhe drita e vogël u ndje edhe më e guximshme.$s$,
    $s$Atëherë drita e vogël filloi të shikonte dhomën me sy të tjerë. Pa që, në dritën e saj të verdhë, librat në raft kishin shpinë me ngjyra të ngrohta. Ariu i madh mbi karrige dukej sikur buzëqeshte. Perdet me retë dukeshin sikur lëviznin ngadalë, si re të vërteta në qiellin e mbrëmjes. Errësira nuk ishte më aq e frikshme, kur kishte pak dritë në mes të saj.$s$,
    $s$Dhe drita e vogël kuptoi diçka të rëndësishme: errësira nuk ishte armiku i saj. Pa errësirë, ajo s'do të shihej fare. Ishte pikërisht errësira që e bënte dritën e saj të vogël të dukej kaq e bukur e kaq e dobishme. Ishin bashkë, drita dhe errësira, si dy shoqe që kanë nevojë për njëra-tjetrën.$s$,
    $s$Beni u shtri përsëri, me kokën nga drita e vogël. Sytë filluan t'i rëndoheshin. «Natën e mirë, dritë e vogël», pëshpëriti. Dhe drita e vogël, nëse do të kishte gojë, do t'i kishte thënë: «Natën e mirë, Ben. Fli i qetë. Unë jam këtu, dhe do të jem këtu gjithë natën.»$s$,
    $s$Beni e zuri gjumi, me një dorë të shtrirë drejt dritës. Dhe drita e vogël ndriçoi gjithë natën, butë e e qëndrueshme, duke ruajtur dhomën: librat, ariun, perdet, pallton e babait. Nuk kishte më frikë. Sepse kishte kuptuar se ishte e vogël, por që në errësirë, edhe drita më e vogël mjafton për ta bërë dikë të ndihet i sigurt.$s$,
    $s$Dhe kur, në mëngjes, dielli hyri nga dritarja, drita e vogël e natës u zbeh dhe pushoi. Ishte lodhur, por ishte e lumtur. Kishte punuar gjithë natën. Dhe nuk e priste dot mbrëmjen tjetër, kur errësira do të vinte përsëri, dhe ajo do të ndizej, për Benin.$s$
  ]::text[],
  array['sleep', 'emotions']::text[], 0, 60, 10, 'moon',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gdritaenates" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gdritaenates)"/><rect x="112" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M122 23Q122 26 125 26Q122 26 122 29Q122 26 119 26Q122 26 122 23Z" fill="#F3EBD9"/><circle cx="136" cy="24" r="5" fill="#F3EBD9"/><path d="M129 14V54M112 34H146" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="18" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="21" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><circle cx="30" cy="30" r="22" fill="#E7B04B"/><circle cx="42" cy="22" r="20" fill="#F8EEE3"/><path d="M52 40Q52 44 56 44Q52 44 52 48Q52 44 48 44Q52 44 52 40Z" fill="#E7B04B"/><path d="M58 7Q58 10 61 10Q58 10 58 13Q58 10 55 10Q58 10 58 7Z" fill="#E7B04B" opacity="0.8"/></g></svg>$s$,
  'published', false, 430, 'editor'
),
(
  $s$tri-dite-me-nastradinin$s$, 'sq', $s$Tri ditë me Nastradinin$s$,
  $s$Tri histori të vjetra me Nastradinin, të njohura në gjithë Ballkanin: kusia që polli, xhaketa që hëngri dhe hëna që ra në pus.$s$,
  array[
    $s$Në një qytet të vogël, me rrugë me kalldrëm dhe me një pazar që mbushej çdo të enjte, jetonte një burrë me çallmë të madhe dhe me një gomar gri. Quhej Nastradin. Disa thoshin se ishte budalla, të tjerë thoshin se ishte njeriu më i zgjuar i qytetit. Ti do të vendosësh vetë, pasi të dëgjosh çfarë bëri në tri ditë.$s$,
    $s$Dita e parë. Nastradini shkoi te fqinji i tij, një tregtar shumë koprrac, dhe i kërkoi hua një kusi të madhe bakri për të gatuar. Tregtari ia dha me mërzi. Pas dy ditësh, Nastradini ia ktheu kusinë, dhe brenda saj kishte një kusi të vogël, sa një filxhan. «Ç'është kjo?» pyeti tregtari. «Kusia jote polli», tha Nastradini. «Ky është i vogli i saj.»$s$,
    $s$Tregtari u habit, por s'tha asgjë. Mendoi: «Po qe se ky budalla më sjell kusi më shumë, aq më mirë për mua.» Dhe e futi kusinë e vogël në dollap me gëzim.$s$,
    $s$Pas një jave, Nastradini erdhi përsëri dhe kërkoi kusinë e madhe. Tregtari ia dha me buzëqeshje. Por kaluan dy ditë, kaluan dy javë, dhe kusia s'u kthye. Më në fund, tregtari trokiti në derën e Nastradinit. «Ku është kusia ime?» «Ah, fqinj», tha Nastradini me fytyrë të trishtuar, «kusia jote vdiq.» «Si vdiq? Kusitë nuk vdesin!» bërtiti tregtari. Nastradini ngriti supet: «Kur besove se pjell, pse s'beson se vdes?»$s$,
    $s$Dhe ndërsa tregtari qëndronte me gojë hapur, Nastradini i dha mbrapsht kusinë, të pastër dhe të shkëlqyer, dhe i tha me një shkelje syri: «Merre. Kisha dashur vetëm të të tregoja se kur lakmia na zë sytë, besojmë çdo gjë që na pëlqen.»$s$,
    $s$Dita e dytë. Në qytet bëhej një dasmë e madhe dhe Nastradini shkoi me rrobat e punës, me pluhur në mëngë e me baltë në këpucë. Në derë e lanë në një cep, larg tryezës, dhe askush s'i ofroi as një copë bukë. Nastradini u ngrit pa folur, u kthye në shtëpi dhe veshi xhaketën e tij më të mirë, me kopsa që shkëlqenin dhe me qëndisje në jakë.$s$,
    $s$Kur u kthye në dasmë, i zoti i shtëpisë vrapoi ta pritte. «Urdhëroni, urdhëroni!» E uli në krye të tryezës dhe i vuri përpara pilaf, mish, byrek dhe bakllava. Nastradini mori një lugë pilaf dhe e afroi te xhepi i xhaketës. «Ha, xhaketa ime, ha», i tha. «Ha se ty të ftuan, jo mua.»$s$,
    $s$Të gjithë heshtën. I zoti i shtëpisë u skuq deri në veshë. Pastaj, ngadalë, filloi të qeshte, dhe me të qeshën të gjithë dasmorët. Atë natë mësuan diçka që e mbajtën mend gjatë: njeriun e çmon për atë që është, jo për rrobat që ka veshur.$s$,
    $s$Dita e tretë. Ishte një mbrëmje vere e ngrohtë dhe Nastradini shkoi te pusi i oborrit për të mbushur kovën me ujë. U përkul mbi grykën e pusit dhe pa poshtë, në ujin e zi, një rreth të bardhë e të ndritshëm. «O Zot!» thirri. «Hëna ka rënë në pus!»$s$,
    $s$Pa humbur kohë, mori litarin e gjatë, lidhi një grep në fund dhe e lëshoi në pus. «Mos u tremb, hënë», thoshte, «tani të nxjerr unë.» E tundi litarin majtas e djathtas, derisa grepi u kap pas një guri në fund të pusit. «Të kapa!» thirri Nastradini dhe tërhoqi me gjithë forcën.$s$,
    $s$Tërhoqi njëherë, tërhoqi dy herë. Herën e tretë, guri u lëshua papritur dhe Nastradini ra pas, me shpinë mbi bar, me këmbët përpjetë. Për një çast qëndroi ashtu, i shtangur. Pastaj hapi sytë dhe pa lart në qiell: hëna ishte atje, e plotë, e bardhë dhe e qetë mbi çatitë e qytetit.$s$,
    $s$Nastradini psherëtiu i kënaqur. «Epo», tha, duke fshirë djersën nga balli, «u rraha pak, por të paktën hëna u kthye në vendin e saj.» Gomari i tij, nga ahuri, lëshoi një pallje të gjatë, sikur qeshte.$s$,
    $s$Atë natë Nastradini fjeti i qetë, me dritaren hapur, që hëna të ndriçonte dhomën e tij. Dhe nëse ndonjë natë do të shohësh hënën te uji i një pellgu, mos u tremb. Ajo s'ka rënë. Thjesht, si Nastradini, po shikon veten në pasqyrë. Natën e mirë.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 48, 144, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gtriditemenastradinin" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gtriditemenastradinin)"/><circle cx="93.1" cy="9.2" r="1.3" fill="#F3EBD9" opacity="0.7"/><circle cx="39.9" cy="34.5" r="0.9" fill="#F3EBD9" opacity="0.7"/><circle cx="24.4" cy="25.7" r="1.3" fill="#F3EBD9" opacity="0.7"/><circle cx="104.8" cy="9.4" r="0.8" fill="#F3EBD9" opacity="0.7"/><circle cx="126.8" cy="22" r="11" fill="#F3EBD9"/><circle cx="120.8" cy="18" r="10" fill="#1E3446"/><path d="M0 91.5Q40 78.4 80 88.4T160 92.3V120H0Z" fill="#24455A"/><path d="M0 97.1Q40 93.8 80 101.8T160 102.4V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="26" cy="38" rx="18" ry="11" fill="#F3EBD9"/><path d="M36 32Q44 24 46 16L54 18Q56 26 52 30L44 38Z" fill="#F3EBD9"/><ellipse cx="52" cy="21" rx="5" ry="7" fill="#F3EBD9" transform="rotate(30 52 21)"/><ellipse cx="46" cy="9" rx="2.2" ry="7" fill="#F3EBD9" transform="rotate(-15 46 9)"/><ellipse cx="51" cy="9" rx="2.2" ry="7" fill="#F3EBD9" transform="rotate(10 51 9)"/><circle cx="51" cy="18" r="1.1" fill="#24455A"/><path d="M12 46L11 60M18 47L18 60M34 47L34 60M40 46L41 60" fill="none" stroke="#F3EBD9" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><path d="M8 36Q2 44 4 50" fill="none" stroke="#F3EBD9" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><circle cx="4" cy="51" r="2" fill="#F3EBD9"/></g></svg>$s$,
  'published', false, 440, 'editor'
),
(
  $s$kepucari-dhe-xhuxhet$s$, 'sq', $s$Këpucari dhe xhuxhët$s$,
  $s$Sipas vëllezërve Grim: një këpucar i varfër gjen çdo mëngjes këpucë të qepura nga dikush. Kur zbulon kush janë ndihmësit e natës, vendos t'u kthejë mirësinë.$s$,
  array[
    $s$Na ishte një herë një këpucar i ndershëm, që punonte shumë, por që ishte bërë aq i varfër, sa i kishte mbetur lëkurë vetëm për një palë këpucë. Një mbrëmje, e preu lëkurën me kujdes, e vuri mbi tryezën e punës dhe tha: «Nesër në mëngjes do t'i qep.» Pastaj shkoi të flinte, i lodhur, por me zemër të qetë.$s$,
    $s$Në mëngjes, kur zbriti në punishte, nuk u besoi syve. Në tryezë qëndronte një palë këpucë e mbaruar, e qepur aq bukur, aq e drejtë dhe aq e pastër, sa s'kishte asnjë pe të shtrembër. Ishin këpucë të denja për një mbret. Këpucari i mori në duar dhe i rrotulloi. «Kush i ka bërë?» pyeti gruan. As ajo s'e dinte.$s$,
    $s$Pak më vonë, në dyqan hyri një blerës. Këpucët i pëlqyen aq shumë, sa i pagoi më shumë se zakonisht. Me ato para, këpucari bleu lëkurë për dy palë këpucë. Në mbrëmje i preu dhe i la mbi tryezë. Dhe në mëngjes, ishin përsëri gati: dy palë këpucë të shkëlqyera.$s$,
    $s$Kështu vazhdoi çdo natë. Sa lëkurë priste në mbrëmje, aq këpucë gjente në mëngjes. Shpejt, njerëzit nga gjithë qyteti filluan të vinin te dyqani i tij, sepse thoshin se këpucët e tij ishin më të mirat e të gjithë vendit. Këpucari dhe gruaja e tij nuk ishin më të varfër, dhe kishin bukë, dru dhe vaj për dimër.$s$,
    $s$Një mbrëmje, para Krishtlindjes, këpucari i tha gruas: «Si thua, a të rrimë zgjuar sonte dhe të shohim kush na ndihmon kaq shumë?» Gruaja u pajtua. Lanë një qiri të ndezur, u fshehën pas perdes së dhomës së punës dhe pritën me sy hapur.$s$,
    $s$Kur ora ra mesnatë, nga oxhaku zbritën dy xhuxhë të vegjël, të vockël, sa një dorë njeriu. Ishin zbathur dhe pothuajse lakuriq, me vetëm disa lecka të vjetra në trup. U ulën në tryezën e punës, morën lëkurën e prerë dhe filluan të shponin, të qepnin e të godisnin me çekiçë të vegjël, aq shpejt e me aq mjeshtëri, sa këpucari s'i shqiti dot sytë.$s$,
    $s$Punuan gjithë natën pa pushim, duke kënduar me zë të hollë. Kur mbaruan, i rreshtuan këpucët bukur në tryezë dhe u zhdukën nga oxhaku, si të ishin bërë tym. Këpucari dhe gruaja dolën nga pas perdes, ende të mahnitur.$s$,
    $s$Në mëngjes, gruaja tha: «Xhuxhët na kanë bërë të pasur. Por ke parë si janë? Lakuriq e të zbathur, në këtë dimër! Duhet t'i falënderojmë. Unë do t'u qep nga një këmishë, një xhaketë, një jelek dhe një palë pantallona. Do t'u thur edhe nga një palë çorape.» «Dhe unë do t'u bëj nga një palë këpucë të vogla», tha këpucari me gëzim.$s$,
    $s$Gjithë javën punuan për xhuxhët. Gruaja qepi rroba të vogla me copa të ngjyrosura, me kopsa të vockla si kokrra orizi. Këpucari bëri dy palë këpucë të vogla prej lëkure të butë, me lidhëse të kuqe. Dhe atë mbrëmje, në vend të lëkurës së prerë, i vunë dhuratat mbi tryezë. Pastaj u fshehën përsëri pas perdes.$s$,
    $s$Në mesnatë, xhuxhët zbritën nga oxhaku dhe u ulën në tryezë për të punuar. Por në vend të lëkurës, gjetën rrobat e vogla. Në fillim u habitën. Pastaj filluan të gëzoheshin. U veshën me shpejtësi, me këmisha, xhaketa e pantallona, me çorape e me këpucë, dhe filluan të këndonin: «Tani që jemi kaq të bukur, pse të bëjmë më këpucarë?»$s$,
    $s$Kërcyen e hidheshin mbi tryezë, mbi karrige e mbi stol, rrotulloheshin përpara qirit dhe shikonin hijet e tyre në mur. Pastaj, duke kërcyer, dolën nga dera dhe u zhdukën në natën me borë. Nuk u kthyen më kurrë.$s$,
    $s$Por këpucari nuk u mërzit. Kishte mësuar nga xhuxhët mjeshtërinë e qepjes, duke i parë atë natë, dhe nga ajo ditë qepi vetë këpucë po aq të bukura. Dhe kurrë s'e harroi mirësinë që i kishin bërë. Çdo dimër, lente pranë oxhakut një palë çorape të ngrohta e të vogla, për çdo rast, nëse dikush i vogël kishte ftohtë.$s$,
    $s$Thonë se këpucari dhe gruaja e tij jetuan të lumtur për shumë vite, dhe se dyqani i tyre ishte gjithmonë i hapur për ata që s'kishin para për këpucë. «Dikur», thoshte këpucari, «edhe neve na ndihmoi dikush, pa kërkuar asgjë. Tani është radha jonë.»$s$
  ]::text[],
  array['classic', 'lessons']::text[], 36, 96, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkepucaridhexhuxhet" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkepucaridhexhuxhet)"/><circle cx="122.5" cy="8.5" r="1.2" fill="#F3EBD9" opacity="0.7"/><path d="M129.3 14.099999999999998Q129.3 16.9 132.10000000000002 16.9Q129.3 16.9 129.3 19.7Q129.3 16.9 126.50000000000001 16.9Q129.3 16.9 129.3 14.099999999999998Z" fill="#F3EBD9" opacity="0.9"/><circle cx="55.2" cy="14.8" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="27.4" cy="16.6" r="0.8" fill="#F3EBD9" opacity="0.7"/><path d="M115.9 11.6Q115.9 15 119.30000000000001 15Q115.9 15 115.9 18.4Q115.9 15 112.5 15Q115.9 15 115.9 11.6Z" fill="#F3EBD9" opacity="0.9"/><circle cx="130" cy="22" r="11" fill="#F3EBD9"/><circle cx="124" cy="18" r="10" fill="#1E3446"/><path d="M0 89.7Q40 82.8 80 92.8T160 84.3V120H0Z" fill="#24455A"/><path d="M0 101.7Q40 91.4 80 99.4T160 96.4V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M18 8H38V40Q50 40 56 48V56H14V44Q18 40 18 34Z" fill="#F3EBD9"/><rect x="14" y="8" width="28" height="6" rx="2" fill="#E7B04B"/><path d="M22 22H34M22 28H34" fill="none" stroke="#24455A" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><rect x="14" y="54" width="42" height="4" rx="2" fill="#8A5A44"/></g></svg>$s$,
  'published', false, 450, 'editor'
),
(
  $s$ylli-qe-ra-ne-oborr$s$, 'sq', $s$Ylli që ra në oborr$s$,
  $s$Një natë vere, një yll i vogël bie në oborrin e Elit. Eli dhe gjyshi duhet të gjejnë një mënyrë për ta kthyer në qiell para agimit.$s$,
  array[
    $s$Ishte një natë vere në fshat, e ngrohtë e e qetë. Eli dhe gjyshi i tij ishin shtrirë në oborr, mbi një batanije të vjetër, nën pemën e mollës, dhe shikonin yjet. Gjyshi ia tregonte me gisht: «Ajo është Rruga e Qumështit. Ato janë Shtatë Motrat. Dhe ai i kuqi, atje poshtë, është Marsi.»$s$,
    $s$Papritur, Eli pa një dritë që kaloi nëpër qiell, shpejt, me një bisht të gjatë prej drite. «Gjysh! Një yll po bie!» «Bëj një dëshirë», tha gjyshi. Por ylli nuk u zhduk si yjet e tjerë që bien. Erdhi gjithnjë e më afër, gjithnjë e më i madh, dhe me një zhurmë të lehtë, si një kumbonë e vogël, ra pikërisht në mes të oborrit, pranë kopshtit me domate.$s$,
    $s$Eli dhe gjyshi u ngritën me vrap. Në bar, mes domateve, ishte një yll i vogël. Ishte sa një portokall, me pesë cepa të rrumbullakët, dhe shkëlqente me një dritë të artë që dridhej, si një qiri në erë. Dhe po qante. Lotët e tij ishin si pika të vogla drite që binin në bar dhe zhdukeshin.$s$,
    $s$«Mos qaj, yll i vogël», tha Eli dhe u ul në gjunjë pranë tij. «Çfarë ke?» «Kam rënë!» tha ylli me një zë të hollë, si një zile. «Po luaja me yjet e tjerë, rrotull Hënës, dhe rrëshqita. Dhe tani s'mund të kthehem lart. Nëse s'kthehem para se të lindë dielli, drita ime do të shuhet.»$s$,
    $s$Eli shikoi gjyshin, i shqetësuar. Gjyshi u mendua, duke kruar mjekrën. «Hm», tha. «Si mund ta kthejmë një yll në qiell?» Eli provoi ta hidhte lart, me të gjitha forcat. Ylli u ngrit pak, deri te majat e pemës së mollës, dhe pastaj ra përsëri, butë, në duart e tij. «S'mjafton», tha ylli. «Qielli është shumë lart.»$s$,
    $s$Gjyshi provoi të ngjitej në shkallën e gjatë të hambarit, me yllin në xhep. Por shkalla arrinte vetëm deri te çatia, dhe çatia ishte shumë larg nga yjet. U ul në çati, i lodhur, duke parë qiellin që ishte ende kaq larg. «S'mjafton as kjo», tha.$s$,
    $s$Eli u ul në barin e oborrit dhe mendoi fort. Shikoi pemën e mollës, shikoi hambarin, shikoi kopshtin. Dhe pastaj pa, në qoshe të hambarit, diçka të harruar: balonën e madhe të kuqe të ditëlindjes së tij, që i kishte mbetur nga java e kaluar dhe që ende rrinte e lidhur me një fije pas derës, duke u lëkundur lehtë në erë.$s$,
    $s$«Gjysh!» thirri Eli. «Balona!» Gjyshi u kthye dhe e kuptoi menjëherë. Zbriti nga çatia dhe të dy vrapuan te balona. Ishte ende e fryrë mirë, e madhe e e kuqe, dhe tërhiqej lart sikur të donte të fluturonte. «A do të mjaftojë?» pyeti Eli. «Ndoshta», tha gjyshi. «Por do të na duhet edhe diçka tjetër.»$s$,
    $s$Gjyshi hyri në shtëpi dhe doli me shportën e vogël të qershive, prej thuprash, të lehtë si pupël. Eli e vendosi yllin me kujdes në shportë, mbi një gjethe të madhe molle, si në një shtrat. Gjyshi lidhi shportën pas fijes së balonës, me një nyje të fortë, nga ato që përdorte për të lidhur varkën në liqen.$s$,
    $s$Balona u ngrit pak, me shportën poshtë saj, dhe ndaloi në lartësinë e kokës së Elit. Ylli dukej i vogël e i trembur. «A do të mjaftojë?» pyeti ylli. «Edhe një gjë», tha Eli. Mori frymë thellë dhe i fryu shportës nga poshtë, me gjithë forcën, si të fryje qirinjtë e ditëlindjes. Dhe ndoshta ishte fryma e Elit, ndoshta ishte era e natës, ndoshta ishte dëshira që kishte bërë kur pa yllin të binte. Balona filloi të ngrihej.$s$,
    $s$U ngrit mbi pemën e mollës. Mbi çatinë e hambarit. Mbi kodrën pas shtëpisë. Gjithnjë e më lart, gjithnjë e më e vogël, një pikë e kuqe me një dritë të artë poshtë saj, që lëkundej si një fener. «Mirupafshim!» thirri Eli. «Faleminderit!» u dëgjua një zë i hollë, si zile, nga lart.$s$,
    $s$Eli dhe gjyshi ndenjën gjatë në oborr, me kokat lart, duke ndjekur dritën e vogël që ngjitej. Deri sa u bë aq e vogël, sa s'dallohej më nga yjet e tjerë. Dhe pastaj, në një vend bosh të qiellit, pranë Hënës, u ndez një yll i ri. Shkëlqeu një herë, dy herë, tri herë, si për të thënë faleminderit.$s$,
    $s$Gjyshi e përqafoi Elin. «Çfarë dëshire bëre», e pyeti, «kur pe yllin të binte?» Eli buzëqeshi. «Bëra dëshirë që të mund ta ndihmoja.» Pastaj u shtrinë përsëri mbi batanijen nën pemën e mollës. Eli shikoi yllin e ri pranë Hënës dhe ndjeu sytë që i rëndoheshin. Dhe e zuri gjumi aty, në oborr, nën yje, me gjyshin pranë. Dhe ylli i vogël i ndriçoi fytyrën gjithë natën.$s$
  ]::text[],
  array['sleep', 'adventure']::text[], 36, 84, 10, 'star',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gylliqeraneoborr" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gylliqeraneoborr)"/><path d="M86.1 11.3Q86.1 14.9 89.69999999999999 14.9Q86.1 14.9 86.1 18.5Q86.1 14.9 82.5 14.9Q86.1 14.9 86.1 11.3Z" fill="#F3EBD9" opacity="0.9"/><circle cx="149.6" cy="29" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="148.7" cy="26.1" r="1" fill="#F3EBD9" opacity="0.7"/><path d="M96.3 2.6Q96.3 6.2 99.89999999999999 6.2Q96.3 6.2 96.3 9.8Q96.3 6.2 92.7 6.2Q96.3 6.2 96.3 2.6Z" fill="#F3EBD9" opacity="0.9"/><circle cx="121.8" cy="35.1" r="1.5" fill="#F3EBD9" opacity="0.7"/><circle cx="34" cy="22" r="11" fill="#F3EBD9"/><circle cx="40" cy="18" r="10" fill="#1E3446"/><path d="M0 87.8Q40 75.2 80 85.2T160 87.6V120H0Z" fill="#24455A"/><path d="M0 101.8Q40 94.2 80 102.2T160 96.3V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 6L38 24L57 24L42 35L48 53L32 42L16 53L22 35L7 24L26 24Z" fill="#E7B04B"/><path d="M56 4Q56 8 60 8Q56 8 56 12Q56 8 52 8Q56 8 56 4Z" fill="#F3EBD9"/><path d="M8 43Q8 46 11 46Q8 46 8 49Q8 46 5 46Q8 46 8 43Z" fill="#F3EBD9" opacity="0.8"/><circle cx="34" cy="30" r="1.4" fill="#8A5A44"/><circle cx="30" cy="30" r="1.4" fill="#8A5A44"/><path d="M29 35Q32 37.5 35 35" fill="none" stroke="#8A5A44" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 460, 'editor'
),
(
  $s$peshkatari-dhe-peshku-i-arte$s$, 'sq', $s$Peshkatari dhe peshku i artë$s$,
  $s$Sipas Aleksandër Pushkinit: një peshkatar i varfër kap një peshk të artë që plotëson dëshira, por gruaja e tij kërkon gjithnjë e më shumë.$s$,
  array[
    $s$Na ishin një herë një plak dhe një plakë, që jetonin buzë detit blu në një kasolle të vjetër prej balte. Kishin jetuar aty tridhjetë e tre vjet. Plaku peshkonte me rrjetë, dhe plaka tirrte lesh. Ishin të varfër, por kishin njëri-tjetrin dhe zhurmën e detit.$s$,
    $s$Një ditë, plaku hodhi rrjetën në det dhe e nxori vetëm me baltë. E hodhi përsëri dhe e nxori vetëm me bar deti. E hodhi për të tretën herë, dhe kësaj radhe, në rrjetë ishte një peshk. Por jo një peshk i zakonshëm: ishte një peshk i artë, që shkëlqente në diell si një monedhë e re.$s$,
    $s$Dhe peshku i artë foli me zë njeriu: «Plak, më lësho në det. Do të të shpërblej. Do të të jap çfarë të duash.» Plaku u habit aq shumë, sa iu drodhën duart. Kishte peshkuar tridhjetë e tre vjet dhe s'kishte dëgjuar kurrë një peshk të fliste. «Shko në det, peshk i vogël», tha me butësi. «Nuk më duhet asgjë. Shko e noto i lirë.» Dhe e lëshoi në ujë.$s$,
    $s$Kur u kthye në kasolle, ia tregoi gjithçka plakës. Plaka u nxeh. «Ç'budalla je! Pse s'i kërkove asgjë? Të paktën një govatë të re, se e jona është çarë e tëra!» Plaku shkoi te deti dhe thirri: «Peshk i artë, peshk i artë!» Peshku doli. «Çfarë do, plak?» «Më fal, peshk i vogël, por plaka ime do një govatë të re.» «Mos u mërzit», tha peshku. «Shko në shtëpi. E do govatën.»$s$,
    $s$Kur u kthye, plaka kishte një govatë të re. Por në vend që të gëzohej, plaka bërtiti edhe më fort: «Ç'budalla! Një govatë kërkove? Shko te peshku dhe kërkoji një shtëpi të re!» Plaku shkoi te deti, që ishte bërë pak i turbullt. Thirri peshkun dhe ia kërkoi. «Mos u mërzit», tha peshku. «E do shtëpinë.»$s$,
    $s$Kur u kthye, në vend të kasolles prej balte, ishte një shtëpi e bukur, me oxhak tullash e me dyer prej lisi. Plaka ishte ulur te dritarja. Por kur pa plakun, filloi të bërtiste: «Budalla i vjetër! Shko te peshku dhe thuaji që nuk dua të jem më një plakë fshatare. Dua të jem zonjë e madhe, me shërbëtorë e me pallat!»$s$,
    $s$Plaku shkoi te deti, që ishte bërë tani gri e i trazuar. Thirri peshkun. «Çfarë do, plak?» Plaku e uli kokën. «Më fal, peshk i vogël, por plaka ime s'më lë të qetë. Do të jetë zonjë e madhe.» «Mos u mërzit», tha peshku. «Shko në shtëpi.» Dhe kur u kthye, plaka ishte në një pallat të madh, e veshur me mëndafsh, me unaza ari në gishta, me shërbëtorë rreth e qark. Plakun e çoi të punonte në ahur.$s$,
    $s$Kaluan disa ditë, dhe plaka u mërzit përsëri. «Shko te peshku», urdhëroi, «dhe thuaji që dua të jem mbretëreshë!» Plaku u tremb. «Ç'thua, grua? Do të të qeshë gjithë mbretëria!» Por plaka nuk dëgjonte. Plaku shkoi te deti, që ishte bërë i zi e i egër. «Peshk i artë, plaka ime do të jetë mbretëreshë.» «Mos u mërzit», tha peshku. «Do të jetë.»$s$,
    $s$Dhe plaka u bë mbretëreshë, në një pallat edhe më të madh, me ushtarë, me kurorë të artë e me oborrtarë që i përkuleshin. Por as kjo nuk i mjaftoi. Pas pak kohësh thirri plakun. «Nuk dua të jem më mbretëreshë», tha. «Dua të jem zonja e detit. Dua që peshku i artë të më shërbejë mua, të jetojë në pallatin tim dhe të bëjë gjithçka që them unë.»$s$,
    $s$Plaku nuk guxoi të kundërshtonte. Shkoi te deti. Deti ishte bërë një stuhi e zezë, me valë të mëdha që përplaseshin në shkëmbinj e me erë që ulërinte. Plaku thirri me zë të dridhur: «Peshk i artë, peshk i artë!» Peshku doli nga valët. «Çfarë do, plak?»$s$,
    $s$«Më fal, peshk i vogël», tha plaku me lot në sy. «Plaka ime s'do të jetë më mbretëreshë. Do të jetë zonja e detit, dhe do që ti t'i shërbesh asaj.» Peshku nuk tha asgjë. Vetëm tundi bishtin e artë në ujë dhe u zhyt në thellësi të detit. Plaku priti gjatë në breg, por peshku nuk u kthye më.$s$,
    $s$Plaku u kthye në shtëpi. Dhe ç'të shihte: pallati ishte zhdukur. Në vend të tij ishte përsëri kasollja e vjetër prej balte, dhe para saj, ulur në prag, ishte plaka, me rrobat e saj të vjetra, dhe përpara saj, govata e çarë.$s$,
    $s$Plaka e vështroi plakun gjatë, pa folur. Pastaj, për herë të parë pas shumë kohësh, i doli një lot nga syri. «Kishim gjithçka që na duhej», pëshpëriti. «Dhe unë s'e kuptova.» Plaku u ul pranë saj në prag. Deti ishte qetësuar dhe po bëhej përsëri blu. «Kemi ende njëri-tjetrin», tha plaku. «Dhe detin.» Atë mbrëmje, hëngrën bashkë një peshk të vogël që plaku kishte kapur, pranë zjarrit, dhe ishte darka më e shijshme e jetës së tyre.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 48, 120, 10, 'boat',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gpeshkataridhepeshkui" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#C6E3EC"/><stop offset="1" stop-color="#EEF7F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gpeshkataridhepeshkui)"/><circle cx="36.9" cy="22" r="9" fill="#FFF3D6"/><path d="M38.1 34l4 3l4 -3M120.9 28l3 2.4l3 -2.4" fill="none" stroke="#5EA4B6" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><rect x="0" y="76" width="160" height="44" rx="0" fill="#8CC3CF"/><path d="M0 86Q10 82 20 86T40 86T60 86T80 86T100 86T120 86T140 86T160 86" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/><rect x="0" y="100" width="160" height="20" rx="0" fill="#5EA4B6"/><path d="M0 106Q10 102 20 106T40 106T60 106T80 106T100 106T120 106T140 106T160 106" fill="none" stroke="#FFFFFF" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="30" cy="36" rx="18" ry="11" fill="#2A5263"/><path d="M44 36L60 26L58 36L60 46Z" fill="#2A5263"/><circle cx="20" cy="33" r="2" fill="#EEF7F8"/><path d="M28 26Q34 18 40 26Z" fill="#2A5263"/><path d="M26 40Q32 44 38 40" fill="#EEF7F8" opacity="0.3"/><circle cx="8" cy="22" r="2" fill="#E39A55" opacity="0.6"/><circle cx="4" cy="14" r="1.4" fill="#E39A55" opacity="0.5"/><circle cx="10" cy="8" r="1" fill="#E39A55" opacity="0.4"/></g></svg>$s$,
  'published', false, 470, 'editor'
),
(
  $s$kreveti-qe-u-be-anije$s$, 'sq', $s$Krevati që u bë anije$s$,
  $s$Kur fiket drita, krevati i Teos bëhet anije, jorgani bëhet vela dhe ariu bëhet kapiten. Udhëtojnë deri në ishullin e gjumit.$s$,
  array[
    $s$Teo nuk donte të flinte. «Edhe pak lojë», i tha mamasë. «Vetëm pak.» Mamaja buzëqeshi. «Mirë», tha. «Por do të luash në shtrat. Se krevati yt, kur fiket drita, bëhet një anije. Dhe sonte, ka një udhëtim të gjatë për të bërë.» Teo e shikoi me dyshim. Pastaj u fut në shtrat. Mamaja i dha një puthje, fiku dritën dhe doli.$s$,
    $s$Teo priti në errësirë. Për një çast, asgjë. Pastaj ndjeu diçka. Krevati po lëkundej, shumë ngadalë, majtas e djathtas, si në ujë. Teo u ngrit ulur dhe shikoi përreth. Dyshemeja e dhomës ishte zhdukur. Rreth krevatit, kudo, ishte një det i qetë, blu i errët, me valë të vogla që shkëlqenin nën dritën e hënës.$s$,
    $s$Jorgani i tij, ai me vija blu e të bardha, ishte ngritur dhe ishte varur pas dy shkopinjve si një velë e madhe, që fryhej butë në erë. Jastëku ishte bërë një rrotull druri për të drejtuar anijen. Dhe në ballë të anijes, me një kapelë kapiteni në kokë e me një dylbi në dorë, qëndronte ariu i tij i vogël kafe, Bubi.$s$,
    $s$«Mirë se erdhe në bord, marinar Teo!» tha Bubi me zë të thellë kapiteni. «Ke qenë i shpejtë sonte. Jemi gati të nisemi. Destinacioni: Ishulli i Gjumit.» «Ku është ai ishull?» pyeti Teo. «Në fund të detit të natës», tha Bubi. «Por për të arritur atje, duhet të kalojmë disa vende. Merr rrotullën. Ti do të drejtosh.»$s$,
    $s$Teo u ul pranë jastëkut-rrotull dhe e rrotulloi ngadalë. Anija lëvizi përpara, duke çarë valët e qeta. Era ishte e freskët dhe kishte erë kripe. Lart, qielli ishte plot me yje, dhe hëna i ndiqte sikur të donte t'u bënte shoqëri.$s$,
    $s$Së pari kaluan pranë një ishulli të vogël, ku një fener i bardhë rrotullonte dritën e tij: majtas, djathtas, majtas, djathtas. «Ky është Feneri i Dritës së Vogël», tha Bubi. «Ruan anijet që lundrojnë natën.» Feneri ndriçoi anijen e Teos dhe Teo i tundi dorën. Feneri iu përgjigj duke e fikur e ndezur dritën dy herë: përshëndetje.$s$,
    $s$Pastaj kaluan nëpër Detin e Delfinëve. Delfinët dolën nga uji, një nga një, dhe kërcyen rreth anijes, duke bërë rrathë argjendi nën hënë. Njëri prej tyre, i vogli, notoi pranë Teos dhe i spërkati pak ujë në faqe. Teo qeshi. «Natën e mirë, delfinë!» thirri. Dhe delfinët, njëri pas tjetrit, u zhytën në ujë dhe u zhdukën në thellësi, ku shkojnë të flenë.$s$,
    $s$Më pas, deti u bë edhe më i qetë. Valët ishin bërë si fletë xhami. Bubi tregoi me dylbi. «Shiko atje, marinar. Ato janë Retë e Buta.» Mbi ujë notonin re të bardha, të ulëta, si jastëkë të mëdhenj. Anija kaloi mes tyre, dhe retë ia përkëdhelën faqet Teos, të freskëta e të buta si leshi i qengjit. Një re e vogël u ul në buzë të anijes dhe qëndroi aty, si një mace e bardhë.$s$,
    $s$Teo filloi të ndjente sytë të rëndë. Rrotulla i dukej më e rëndë në duar. «Bubi», tha me një zë të vogël, «a jemi afër?» «Shumë afër», tha Bubi. «Por tani duhet të bësh diçka tjetër. Lëre rrotullën. Anija di vetë rrugën nga këtu. Shtrihu në kuvertë dhe shiko yjet.»$s$,
    $s$Teo u shtri në kuvertë, që ishte e butë si dyshek. Bubi e mbuloi me një cep të velës. Yjet lart dukeshin sikur lëviznin ngadalë, si të ishin edhe ata në anije. Anija lëkundej: majtas... djathtas... majtas... djathtas. Valët bënin shhh... shhh... shhh, kur preknin anët e anijes. Dhe hëna ndriçonte e qetë mbi gjithçka.$s$,
    $s$«Bubi», pëshpëriti Teo, «a do të vish edhe ti në ishull?» «Gjithmonë», tha Bubi, dhe u shtri pranë tij, me kapelën e kapitenit mbi sy. «Ku shkon ti, shkoj edhe unë. Kështu bëjnë kapitenët dhe marinarët.» Teo e përqafoi Bubin dhe ndjeu qimet e tij të buta pranë faqes.$s$,
    $s$Dhe pastaj, ngadalë, pa zhurmë, anija preku rërën e butë të Ishullit të Gjumit. Ishte një ishull i vogël e i ngrohtë, me palma që lëkundeshin e me rërë të bardhë si sheqer. Teo nuk e pa, sepse sytë i kishte mbyllur. Por e ndjeu. E ndjeu që kishte arritur.$s$,
    $s$Në mëngjes, kur mamaja hyri në dhomë, gjeti Teon që flinte i shtrirë në shtratin e tij të zakonshëm, me jorganin me vija blu të mbështjellë rreth vetes si një velë, me jastëkun në krahë si një rrotull dhe me ariun Bubi nën mjekër. Dhe kishte pak rërë te këmbët e shtratit. Ose ndoshta ishte vetëm pluhur. Mamaja buzëqeshi dhe s'pyeti asgjë. Sepse e dinte që sonte, anija do të nisej përsëri.$s$
  ]::text[],
  array['sleep', 'adventure']::text[], 0, 72, 10, 'boat',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkrevetiqeubeanije" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkrevetiqeubeanije)"/><path d="M44 23.5Q44 26.3 46.8 26.3Q44 26.3 44 29.1Q44 26.3 41.2 26.3Q44 26.3 44 23.5Z" fill="#F3EBD9" opacity="0.9"/><circle cx="59.5" cy="18.3" r="1.2" fill="#F3EBD9" opacity="0.7"/><path d="M142.5 38Q142.5 41.7 146.2 41.7Q142.5 41.7 142.5 45.400000000000006Q142.5 41.7 138.8 41.7Q142.5 41.7 142.5 38Z" fill="#F3EBD9" opacity="0.9"/><circle cx="43.2" cy="31" r="1.1" fill="#F3EBD9" opacity="0.7"/><circle cx="139.1" cy="41.8" r="1.6" fill="#F3EBD9" opacity="0.7"/><path d="M15.5 20.700000000000003Q15.5 23.1 17.9 23.1Q15.5 23.1 15.5 25.5Q15.5 23.1 13.1 23.1Q15.5 23.1 15.5 20.700000000000003Z" fill="#F3EBD9" opacity="0.9"/><circle cx="141.6" cy="35.7" r="1.4" fill="#F3EBD9" opacity="0.7"/><circle cx="116.6" cy="44" r="1.5" fill="#F3EBD9" opacity="0.7"/><circle cx="133" cy="22" r="11" fill="#F3EBD9"/><circle cx="127" cy="18" r="10" fill="#1E3446"/><path d="M0 86.2Q40 79 80 89T160 89.1V120H0Z" fill="#24455A"/><path d="M0 98.9Q40 91.8 80 99.8T160 97.9V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M6 44H58L50 56H14Z" fill="#F3EBD9"/><path d="M32 44V6" fill="none" stroke="#F3EBD9" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/><path d="M34 8L56 40H34Z" fill="#E7B04B"/><path d="M30 12L12 40H30Z" fill="#FFFFFF" opacity="0.9"/><path d="M0 60Q10 56 20 60T40 60T60 60" fill="none" stroke="#F3EBD9" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
  'published', false, 480, 'editor'
),
(
  $s$rrepa-e-madhe$s$, 'sq', $s$Rrepa e madhe$s$,
  $s$Përrallë popullore ruse: gjyshi mbjell një rrepë që rritet aq e madhe sa s'e shkul dot vetë. I duhet ndihma e të gjithëve, deri te miu më i vogël.$s$,
  array[
    $s$Na ishte një herë një gjysh, që kishte një kopsht të vogël pranë shtëpisë. Një pranverë, mbolli në kopsht disa fara rrepe. I ujiti çdo mëngjes, i hoqi barërat e këqija çdo pasdite dhe u këndoi çdo mbrëmje. «Rritu, rritu, rrepë e vogël», thoshte. «Rritu e ëmbël, rritu e fortë.»$s$,
    $s$Dhe rrepa u rrit. U rrit sa një mollë. U rrit sa një shalqi. U rrit sa një kungull. U rrit aq e madhe, sa dukej si një shkëmb i bardhë me gjethe të gjelbra mbi kokë. Fqinjët vinin ta shikonin dhe tundnin kokën me habi. «S'kemi parë kurrë një rrepë të tillë», thoshin.$s$,
    $s$Erdhi vjeshta, dhe gjyshi vendosi ta shkulte rrepën. U kap pas gjetheve të saj të mëdha dhe tërhoqi. Tërhoqi me të gjithë forcën, deri sa iu skuq fytyra. Por rrepa nuk lëvizi. Ishte e ngulur në tokë si një gur.$s$,
    $s$«Gjyshe!» thirri gjyshi. «Eja të më ndihmosh!» Gjyshja erdhi me përparëse, u kap pas belit të gjyshit, dhe filluan të tërhiqnin. Gjyshja tërhiqte gjyshin, gjyshi tërhiqte rrepën. Tërhoqën e tërhoqën, por rrepa nuk lëvizi.$s$,
    $s$«Mbesë!» thirri gjyshja. «Eja të na ndihmosh!» Mbesa erdhi me vrap nga oborri, me gërshetat që i kërcenin. U kap pas fustanit të gjyshes. Mbesa tërhiqte gjyshen, gjyshja tërhiqte gjyshin, gjyshi tërhiqte rrepën. Tërhoqën e tërhoqën, por rrepa nuk lëvizi.$s$,
    $s$«Qen!» thirri mbesa. «Eja të na ndihmosh!» Qeni, që po flinte në diell, u ngrit duke tundur bishtin dhe kapi me dhëmbë fundin e fustanit të mbesës, butë, që të mos e griste. Qeni tërhiqte mbesën, mbesa tërhiqte gjyshen, gjyshja tërhiqte gjyshin, gjyshi tërhiqte rrepën. Tërhoqën e tërhoqën, por rrepa nuk lëvizi.$s$,
    $s$«Mace!» lehu qeni. «Eja të na ndihmosh!» Maca, që po lante fytyrën me putër mbi gardh, u hodh poshtë dhe u kap pas bishtit të qenit. Maca tërhiqte qenin, qeni tërhiqte mbesën, mbesa tërhiqte gjyshen, gjyshja tërhiqte gjyshin, gjyshi tërhiqte rrepën. Tërhoqën e tërhoqën, e tërhoqën e tërhoqën, por rrepa ende nuk lëvizi.$s$,
    $s$Të gjithë u ulën përtokë të lodhur. «S'ka gjë për të bërë», tha gjyshi, duke fshirë djersën nga balli. «Kjo rrepë do të mbetet aty përgjithmonë.» Atëherë maca vuri re një mi të vogël gri, që i shikonte nga një vrimë në murin e kopshtit, me sy të zinj si kokrra piperi.$s$,
    $s$Zakonisht, maca dhe miu nuk ishin miq. Por atë ditë, maca i tha me zë të butë: «Mi i vogël, a do të na ndihmosh? Të premtoj që s'do të të ndjek sot.» Miu u mendua. Pastaj doli nga vrima. «Unë jam shumë i vogël», tha. «Ç'ndihmë mund të jap unë?» «Ndonjëherë», tha gjyshja, «mjafton pak forcë më shumë.»$s$,
    $s$Miu u kap me këmbët e tij të vockla pas bishtit të maces. Dhe filluan përsëri. Miu tërhiqte macen, maca tërhiqte qenin, qeni tërhiqte mbesën, mbesa tërhiqte gjyshen, gjyshja tërhiqte gjyshin, gjyshi tërhiqte rrepën. Një, dy, tri! Tërhoqën e tërhoqën, dhe... PLLUP!$s$,
    $s$Rrepa doli nga toka! Dhe të gjithë ranë përmbys, njëri mbi tjetrin: gjyshi mbi gjyshen, gjyshja mbi mbesën, mbesa mbi qenin, qeni mbi macen, maca mbi miun. Dhe mbi të gjithë, me gjethet e saj të mëdha që lëkundeshin, ra rrepa e madhe e bardhë. Për një çast, askush s'foli. Pastaj të gjithë filluan të qeshnin, aq shumë sa s'mund të ngriheshin.$s$,
    $s$Atë mbrëmje, gjyshja gatoi një tenxhere të madhe me supë rrepe, aq të madhe sa u mjaftoi të gjithëve. U ulën rreth tryezës: gjyshi, gjyshja, mbesa, qeni, maca dhe, në krye të tryezës, në një karrige të vogël të bërë me një kuti shkrepsesh, miu. «Pa ty», i tha gjyshi, «rrepa do të ishte ende në tokë.» Miu u skuq deri në majë të veshëve.$s$,
    $s$Dhe kështu, që nga ajo ditë, në shtëpinë e gjyshit kishte gjithmonë një vend në tryezë për miun e vogël. Sepse kishin mësuar se kur të gjithë ndihmojnë bashkë, edhe më i vogli bën diferencën. Dhe se asnjë ndihmë nuk është shumë e vogël.$s$
  ]::text[],
  array['classic', 'friendship']::text[], 0, 60, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="grrepaemadhe" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#grrepaemadhe)"/><circle cx="36.1" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 89Q40 77 80 89T160 81.8V120H0Z" fill="#B5D39A"/><path d="M0 98.8Q40 88.5 80 96.5T160 98.9V120H0Z" fill="#93BE7B"/><circle cx="38.2" cy="111.4" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="12.7" cy="112.9" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="125.6" cy="109.4" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="135.1" cy="109.3" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="148.6" cy="106.8" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="149" cy="112.2" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="127.8" cy="115" r="1.6" fill="#FFFFFF" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M32 60Q30 54 22 50Q8 44 14 32Q20 22 32 22Q44 22 50 32Q56 44 42 50Q34 54 32 60Z" fill="#C9A0D6"/><path d="M14 34Q20 26 32 26Q44 26 50 34Q40 30 32 30Q24 30 14 34Z" fill="#FFFFFF" opacity="0.4"/><path d="M32 22Q24 6 18 4Q26 12 30 22Z" fill="#7DA86B"/><path d="M32 22Q32 4 36 0Q36 12 34 22Z" fill="#7DA86B"/><path d="M32 22Q42 6 50 6Q40 12 34 22Z" fill="#7DA86B"/></g></svg>$s$,
  'published', false, 490, 'editor'
),
(
  $s$kucedra-qe-mbante-ujin$s$, 'sq', $s$Kuçedra që mbante ujin$s$,
  $s$Sipas besimeve të vjetra shqiptare, kuçedra e mbyll ujin e burimeve. Por Vera e vogël nuk shkon me shkop: shkon me një këngë.$s$,
  array[
    $s$Në një fshat malor, poshtë një mali të lartë, kishte një burim që s'ishte tharë kurrë. Uji i tij ishte aq i ftohtë sa të dhembnin dhëmbët, dhe aq i ëmbël sa njerëzit vinin nga fshatrat e tjera me bucela vetëm për ta pirë. Rreth burimit rriteshin rrapë të mëdhenj, dhe nën hijen e tyre gratë lanin leshin, ndërsa fëmijët luanin me gurë.$s$,
    $s$Një verë, uji filloi të pakësohej. Në fillim rridhte si një fije e hollë, pastaj pikonte, dhe më në fund pushoi fare. Kopshtet u thanë, dhentë blegërinin nga etja, dhe gratë u detyruan të zbrisnin deri në lumë, një orë rrugë larg.$s$,
    $s$Pleqtë e fshatit u mblodhën nën rrap. «Është kuçedra», tha njëri. «Gjyshërit tanë tregonin se kur shteren burimet, ka hyrë një kuçedër në mal dhe e ka mbyllur ujin me trupin e saj.» Burrat u ngritën në këmbë. «Do të ngjitemi me shkopinj e me zjarr», thanë, «dhe do ta përzëmë.»$s$,
    $s$Vera ishte tetë vjeç dhe i dëgjonte të gjitha, e fshehur pas rrapit. Gjyshja i kishte treguar shpesh për drangujt, trimat me krahë të vegjël nën sqetull, që luftonin kuçedrat. Por Vera s'kishte krahë. Kishte vetëm një zë të bukur, që gjyshja thoshte se të qetësonte si uji i burimit. Dhe mendoi: «Po sikur kuçedra të mos jetë e keqe? Po sikur të jetë thjesht e trishtuar?»$s$,
    $s$Natën, kur të gjithë flinin, Vera mori një copë bukë misri, një shami të kuqe dhe u nis drejt malit. Ndoqi shtratin e thatë të burimit, lart e më lart, mes shkurreve e gurëve. Kur dielli doli, arriti te një shkëmb i madh, ku ishte një shpellë. Nga brenda vinte një frymëmarrje e rëndë dhe e ngadaltë, si era që fryn në oxhak.$s$,
    $s$Vera hyri ngadalë. Në fund të shpellës, mbështjellë si lëmsh mbi gurin nga dilte burimi, rrinte një kuçedër. Ishte e madhe sa një shtëpi, me luspa ngjyrë guri e myshku, me bisht të gjatë e me sy të verdhë. Por sytë e saj nuk ishin të egër. Ishin të lagur. Kuçedra po qante, dhe lotët i binin në gur, aty ku dikur rridhte uji.$s$,
    $s$Vera u drodh e tëra, por nuk iku. Mblodhi gjithë guximin që kishte dhe filloi të këndonte. Këndoi ninullën që i këndonte gjyshja, atë për hënën që ruan delet. Zëri i saj u përhap nëpër shpellë, i hollë e i qartë. Kuçedra e ngriti kokën ngadalë dhe e vështroi.$s$,
    $s$«Ti nuk ke frikë nga unë?» pyeti kuçedra me një zë të thellë, që dridhte gurët. «Pak», tha Vera e sinqertë. «Por më duket se ti ke më shumë frikë se unë. Pse qan?»$s$,
    $s$Kuçedra psherëtiu dhe nga hundët i dolën dy rrjedha avulli. «Jam e fundit nga lloji im», tha. «Të gjitha kuçedrat e tjera kanë ikur prej kohësh. Kam jetuar e vetme në këtë mal për njëqind vjet, dhe e vetmja gjë që më bënte shoqëri ishte zhurma e burimit. Kur uji këndonte, më dukej se s'isha vetëm. Prandaj u shtriva mbi të, ta mbaja afër. Nuk e dija që uji i nevojitej dikujt tjetër.»$s$,
    $s$Vera u mendua pak. Pastaj u ul pranë kokës së madhe të kuçedrës. «Po sikur të mos jesh më e vetme?» i tha. «Po ta lëshosh ujin, unë do të vij çdo mbrëmje dhe do të këndoj për ty. Dhe do të sjell edhe shoqet e mia. Ne dimë shumë këngë, më shumë se burimi.»$s$,
    $s$Kuçedra heshti gjatë. Pastaj, shumë ngadalë, u ngrit nga guri. Pati një gurgullimë, një pëshpëritje, dhe papritur uji shpërtheu i ftohtë e i kristaltë, duke kërcyer mbi gurë e duke vrapuar teposhtë malit. Kuçedra e ndoqi me sy, dhe për herë të parë pas njëqind vjetësh, buzët e saj të mëdha u përkulën në një buzëqeshje.$s$,
    $s$Kur uji arriti në fshat, njerëzit dolën me vrap nga shtëpitë. Burrat, që po mprehnin shkopinjtë, i lanë në tokë. Dhe pak më vonë panë Verën duke zbritur nga mali, me shaminë e kuqe në dorë, duke kënduar. Ajo u tregoi gjithçka, dhe pleqtë dëgjuan me gojë hapur.$s$,
    $s$Që nga ajo verë, çdo mbrëmje e shtunë, fëmijët e fshatit ngjiten te shpella dhe i këndojnë kuçedrës. Ajo i dëgjon e shtrirë pranë burimit, jo më mbi të, dhe ndonjëherë u tregon histori nga koha kur malet ishin të rinj. Burimi s'është tharë më kurrë.$s$,
    $s$Dhe kur dikush në fshat thotë se kuçedrat janë të këqija, gjyshja e Verës buzëqesh dhe thotë: «Ndonjëherë, ajo që duket si përbindësh, është vetëm dikush që ka qenë shumë kohë vetëm.»$s$
  ]::text[],
  array['classic', 'adventure', 'emotions']::text[], 48, 120, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkucedraqembanteujin" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CADAE8"/><stop offset="1" stop-color="#EFF4F8"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkucedraqembanteujin)"/><circle cx="131.3" cy="20" r="8" fill="#FFF3D6"/><path d="M-8.899999999999999 100L31.1 33L71.1 100Z" fill="#A8BCCF"/><path d="M22.1 48.1L31.1 33L40.1 48.1L35.1 53.1L31.1 46.4L27.1 53.1Z" fill="#FFFFFF" opacity="0.9"/><path d="M97.69999999999999 100L137.7 34.8L177.7 100Z" fill="#A8BCCF"/><path d="M128.7 49.5L137.7 34.8L146.7 49.5L141.7 54.4L137.7 47.8L133.7 54.4Z" fill="#FFFFFF" opacity="0.9"/><path d="M40 100L80 58L120 100Z" fill="#7F99B0"/><path d="M71 67.5L80 58L89 67.5L84 70.6L80 66.4L76 70.6Z" fill="#FFFFFF" opacity="0.9"/><path d="M0 105.4Q40 95.2 80 101.2T160 103V120H0Z" fill="#7F99B0"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M6 56Q2 42 14 36Q26 30 24 20Q22 10 32 8L40 4L42 10Q48 12 50 16L44 18Q40 18 38 22Q42 34 34 42Q26 50 30 56Z" fill="#2F4357"/><path d="M24 28L14 18L28 22Z" fill="#2F4357"/><path d="M30 46Q44 40 54 48Q60 54 54 58Q50 50 40 52Z" fill="#2F4357"/><circle cx="40" cy="13" r="1.4" fill="#EFF4F8"/><path d="M16 38l-5 -2l3 5z" fill="#D9644A"/><path d="M12 44l-5 -2l3 5z" fill="#D9644A"/><path d="M10 50l-5 -2l3 5z" fill="#D9644A"/><path d="M46 14Q52 10 56 12" fill="none" stroke="#D9644A" stroke-width="1.2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 500, 'editor'
),
(
  $s$mbreti-i-gjumit$s$, 'sq', $s$Mbreti i Gjumit dhe kështjella e jastëkëve$s$,
  $s$Mbreti i Gjumit ka humbur kurorën, dhe pa të, asnjë fëmijë në mbretëri s'mund të flejë. Princesha Iva e vogël niset ta gjejë nëpër kështjellën e jastëkëve.$s$,
  array[
    $s$Në mbretërinë e Natës, përtej reve, ka një kështjellë të ndërtuar krejt me jastëkë. Muret janë jastëkë të mëdhenj të bardhë, kullat janë jastëkë të gjatë të rrumbullakët, dhe çatitë janë jorganë me pupla. Aty jeton Mbreti i Gjumit, një plak i vogël e i rrumbullakët, me një pizhama të gjatë blu e me pantofla me pompon.$s$,
    $s$Mbreti i Gjumit ka një kurorë të veçantë. Nuk është prej ari, por prej yjesh të vegjël e të butë, që shkëlqejnë si xixëllonja. Çdo mbrëmje, ai vë kurorën në kokë dhe del në ballkonin e kështjellës. Dhe kur e vë, nga kurora dalin mijëra pika drite, që fluturojnë nëpër botë dhe hyjnë nga dritaret e fëmijëve. Kur një pikë drite prek ballin e një fëmije, fëmija bie në gjumë.$s$,
    $s$Por një mbrëmje, ndodhi diçka e tmerrshme. Mbreti i Gjumit kërkoi kurorën e tij dhe s'e gjeti. Nuk ishte në jastëkun e saj të kuq. Nuk ishte në dollap. Nuk ishte nën fron. «Kurora ime!» thirri Mbreti. «Ku është kurora ime?» Dhe në gjithë botën, atë mbrëmje, fëmijët nuk binin dot në gjumë.$s$,
    $s$Në një shtëpi, vajza e vogël Iva ishte shtrirë me sytë hapur. Ishte vonë, shumë vonë, por gjumi s'po vinte. Dhe papritur, nga dritarja hyri një zog i vogël i bardhë, me pupla si borë. «Iva», tha zogu, «më dërgon Mbreti i Gjumit. Ka humbur kurorën. Kemi nevojë për një fëmijë që të na ndihmojë ta gjejmë, se vetëm fëmijët e njohin dritën e saj. A vjen?»$s$,
    $s$Iva u ngrit menjëherë. Zogu i bardhë u bë i madh, aq i madh sa Iva mund t'i hipte në shpinë. Fluturuan nga dritarja, mbi çatitë, mbi re, deri te kështjella e jastëkëve. Mbreti i Gjumit i priti te porta, me pizhamën blu e me fytyrë të shqetësuar. «Faleminderit që erdhe», tha. «Pa kurorën, gjithë fëmijët e botës mbeten zgjuar.»$s$,
    $s$Iva filloi të kërkonte. Në sallën e madhe, kërkoi mes jastëkëve të mëdhenj, por gjeti vetëm një çorape të humbur. Në kuzhinë, ku gatuhej qumësht i ngrohtë me mjaltë, kërkoi nën filxhanë, por gjeti vetëm thërrime biskotash. Në bibliotekë, ku ishin të gjitha përrallat e botës, kërkoi mes librave, por gjeti vetëm një faqe të palosur.$s$,
    $s$Pastaj Iva arriti në një dhomë të vogël në majë të kullës më të lartë. Ishte dhoma e lojërave, plot me lodra të vjetra e me kuti. Dhe në qoshe, ishte një kotelë e vogël gri, e mbështjellë si top, që flinte e qetë. Dhe nën putrat e saj, Iva pa një dritë të butë që shkëlqente si xixëllonja.$s$,
    $s$Iva u afrua ngadalë. Ishte kurora! Kotela e vogël e kishte marrë për lodër, e kishte rrokullisur nëpër korridore, deri në dhomën e lojërave, dhe pastaj ishte shtrirë mbi të. Dhe drita e kurorës, natyrisht, e kishte vënë në gjumë menjëherë. Iva qeshi pa zë. Pastaj, me shumë kujdes, që të mos e zgjonte kotelën, e nxori kurorën nga poshtë putrave të saj.$s$,
    $s$Iva vrapoi poshtë shkallëve, me kurorën në duar, dhe ia dha Mbretit. Mbreti e përqafoi aq fort, sa i ra pantofla. «Ti e gjete!» thirri. «Ku ishte?» «Te kotela», tha Iva. «Po flinte mbi të.» Mbreti qeshi me zë. «Natyrisht! Kush tjetër do të kishte guxim të flinte mbi kurorën e gjumit?»$s$,
    $s$Mbreti e vuri kurorën në kokë dhe doli në ballkon. Kurora filloi të shkëlqente, dhe nga yjet e saj dolën mijëra pika drite, që fluturuan nëpër gjithë botën, si një shi drite i ngadaltë. Iva i shikoi të shpërndaheshin mbi qytete, mbi fshatra, mbi dete e mbi male, dhe të hynin nga dritaret, një nga një, te fëmijët që po prisnin.$s$,
    $s$«Dhe tani», tha Mbreti, «është radha jote.» Mori një pikë drite nga kurora, më të madhen e më të bukurën, dhe ia vuri Ivës në pëllëmbë. Ishte e ngrohtë, si një zemër e vogël. «Kjo është për ty», tha. «Kthehu në shtëpi, shtrihu në shtratin tënd, dhe vëre në ballë. Dhe faleminderit, princeshë Iva.»$s$,
    $s$Zogu i bardhë e çoi Ivën në shtëpi, nëpër re e mbi çati, dhe e la në dritaren e saj. Iva u fut nën jorgan, mbylli sytë dhe vuri pikën e dritës në ballë. Ndjeu një ngrohtësi të ëmbël që i përhapej nga balli te sytë, nga sytë te faqet, nga faqet te gjithë trupi. Dhe pastaj, gjumi erdhi, i butë e i thellë.$s$,
    $s$Që nga ajo natë, Mbreti i Gjumit e mban kurorën në një kuti me çelës. Por kotelës gri i ka bërë një kurorë të vogël të sajën, prej pambuku, që të mos ia marrë më. Dhe çdo mbrëmje, kur Mbreti del në ballkon, i dërgon një pikë drite të veçantë Ivës. Sonte, kur të mbyllësh sytë, ndoshta do të ta dërgojë edhe ty.$s$
  ]::text[],
  array['sleep', 'adventure']::text[], 36, 84, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gmbretiigjumit" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#1E3446"/><stop offset="1" stop-color="#2E5566"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gmbretiigjumit)"/><path d="M16.5 26.1Q16.5 28.5 18.9 28.5Q16.5 28.5 16.5 30.9Q16.5 28.5 14.1 28.5Q16.5 28.5 16.5 26.1Z" fill="#F3EBD9" opacity="0.9"/><circle cx="130.2" cy="38.8" r="1.2" fill="#F3EBD9" opacity="0.7"/><path d="M148.9 15.5Q148.9 19.2 152.6 19.2Q148.9 19.2 148.9 22.9Q148.9 19.2 145.20000000000002 19.2Q148.9 19.2 148.9 15.5Z" fill="#F3EBD9" opacity="0.9"/><circle cx="119.5" cy="18.1" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="143.9" cy="15" r="1.5" fill="#F3EBD9" opacity="0.7"/><path d="M134 5.4Q134 9 137.6 9Q134 9 134 12.6Q134 9 130.4 9Q134 9 134 5.4Z" fill="#F3EBD9" opacity="0.9"/><circle cx="51.7" cy="16.7" r="1.2" fill="#F3EBD9" opacity="0.7"/><circle cx="37.7" cy="22" r="11" fill="#F3EBD9"/><circle cx="43.7" cy="18" r="10" fill="#1E3446"/><path d="M0 90.5Q40 73.1 80 83.1T160 86.7V120H0Z" fill="#24455A"/><path d="M0 103.5Q40 92 80 100T160 103V120H0Z" fill="#1A3344"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M10 48L12 22L22 34L32 14L42 34L52 22L54 48Z" fill="#E7B04B"/><rect x="10" y="46" width="44" height="8" rx="2" fill="#E7B04B"/><circle cx="32" cy="14" r="3" fill="#E7B04B"/><circle cx="12" cy="22" r="2.4" fill="#E7B04B"/><circle cx="52" cy="22" r="2.4" fill="#E7B04B"/><circle cx="22" cy="50" r="2" fill="#D9644A"/><circle cx="32" cy="50" r="2.2" fill="#4A9C9A"/><circle cx="42" cy="50" r="2" fill="#D9644A"/></g></svg>$s$,
  'published', false, 510, 'editor'
),
(
  $s$kuleci-qe-iku$s$, 'sq', $s$Kuleçi që iku nga dritarja$s$,
  $s$Përrallë popullore ruse: gjyshja pjek një kuleç të rrumbullakët, që rrokulliset nga dritarja dhe nis udhëtimin e vet nëpër pyll. Do t'ia dalë t'u shpëtojë të gjithëve?$s$,
  array[
    $s$Na ishin një herë një gjysh dhe një gjyshe. Një mëngjes, gjyshi i tha gjyshes: «Më piq një kuleç, se më ka marrë malli.» «Po s'kemi miell», tha gjyshja. «Fshije arkën e miellit, kruaje fundin e thesit, dhe do të gjesh sa për një kuleç të vogël», tha gjyshi.$s$,
    $s$Gjyshja fshiu arkën dhe kruajti thesin, dhe mblodhi dy grushta miell. E përzjeu me ajkë, e gatoi, i dha formën e një topi të rrumbullakët dhe e futi në furrë. Kur doli, kuleçi ishte i artë, i fryrë dhe aromatik. Gjyshja e vuri në dritare që të ftohej.$s$,
    $s$Kuleçi ndenji aty pak, dhe u mërzit. «Pse të rri këtu e të pres të më hanë?» mendoi. U rrokullis nga dritarja në stol, nga stoli në dysheme, nga dyshemeja te dera, nga dera në oborr, nga oborri në rrugë, dhe iku: rrokull, rrokull, rrokull, drejt pyllit.$s$,
    $s$Kuleçi rrokullisej nëpër shteg, kur takoi një lepur. «Kuleç, kuleç, do të të ha!» tha lepuri. «Mos më ha, lepurush i bardhë», tha kuleçi, «se do të të këndoj një këngë.» Dhe këndoi: «Jam kuleçi i rrumbullakët, jam i pjekur, jam i artë. Gjyshit i ika, gjyshes i ika, edhe ty, lepur, do të të iki!» Dhe u rrokullis tutje, aq shpejt sa lepuri s'arriti ta kapte.$s$,
    $s$Rrokullisej kuleçi, kur takoi një ujk. «Kuleç, kuleç, do të të ha!» «Mos më ha, ujk gri, se do të të këndoj një këngë.» «Jam kuleçi i rrumbullakët, jam i pjekur, jam i artë. Gjyshit i ika, gjyshes i ika, lepurit i ika, edhe ty, ujk, do të të iki!» Dhe u rrokullis tutje, mes pemëve, aq shpejt sa ujku mbeti me gojë hapur.$s$,
    $s$Rrokullisej kuleçi, kur takoi një ari. «Kuleç, kuleç, do të të ha!» «Mos më ha, ari me këmbë të shtrembra, se do të të këndoj një këngë.» «Jam kuleçi i rrumbullakët, jam i pjekur, jam i artë. Gjyshit i ika, gjyshes i ika, lepurit i ika, ujkut i ika, edhe ty, ari, do të të iki!» Dhe u rrokullis tutje, dhe ariu, që ishte i ngadaltë, s'e kapi dot.$s$,
    $s$Rrokullisej kuleçi, gjithnjë e më krenar, kur takoi dhelprën. Dhelpra ishte e kuqe, me bisht të bukur e me sy dinakë. «Ah, kuleç», tha ajo me zë të ëmbël, «sa i bukur që je! Sa i artë! Kam dëgjuar që di të këndosh një këngë të mrekullueshme. A ma këndon edhe mua?»$s$,
    $s$Kuleçi u gëzua që dikush e lavdëronte, dhe këndoi: «Jam kuleçi i rrumbullakët, jam i pjekur, jam i artë. Gjyshit i ika, gjyshes i ika, lepurit i ika, ujkut i ika, ariut i ika, edhe ty, dhelpër, do të të iki!» «Ah, sa këngë e bukur!» tha dhelpra. «Por jam plakur dhe s'dëgjoj mirë. Hajde, ulu mbi hundën time dhe këndoje edhe një herë, më fort.»$s$,
    $s$Kuleçi u hodh mbi hundën e dhelprës. Por pikërisht kur po hapte gojën për të kënduar, dhelpra e hodhi lart, në ajër, që ta kapte me gojë. Kuleçi kuptoi, në atë çast, që lavdërimet e dhelprës kishin qenë një kurth. Dhe ndërsa binte, u rrotullua në ajër, ra mbi një gur, u hodh si top dhe u rrokullis teposhtë kodrës, më shpejt se kurrë.$s$,
    $s$Rrokull, rrokull, rrokull, poshtë kodrës, nëpër lëndinë, mbi urë, nëpër fushë. Dhelpra vrapoi pas tij, por kuleçi rrokullisej teposhtë, dhe teposhtë asgjë s'rrokulliset më shpejt se një kuleç i rrumbullakët. Më në fund, pa para vetes një shtëpi të njohur, me një dritare të hapur. Ishte shtëpia e gjyshit dhe e gjyshes!$s$,
    $s$Kuleçi u hodh mbi pragun e dritares dhe ra drejt e në shportën e bukës. Gjyshi dhe gjyshja, që e kishin kërkuar gjithë ditën, u habitën kur e panë. «Ku ke qenë, kuleç?» pyeti gjyshja. Dhe kuleçi, i lodhur, i pluhurosur, por i shëndoshë, ua tregoi të gjitha: për lepurin, për ujkun, për ariun dhe për dhelprën e dinakë.$s$,
    $s$«Ke mësuar diçka sot», tha gjyshi. «Kujdes nga ata që të lavdërojnë shumë. Dhe mos u mburr kurrë, se mburrja të çon drejt e në gojën e dhelprës.» Kuleçi tundi kokën, ose të paktën, aq sa mund ta tundë kokën një kuleç.$s$,
    $s$Dhe a e hëngrën? Jo. Gjyshi tha se një kuleç kaq i guximshëm meritonte të rrinte në shtëpi e t'u tregonte përralla nipërve. E vunë mbi raft, pranë dritares, nga ku shikonte pyllin. Gjyshja piqte kuleçë të tjerë për të ngrënë, por para se t'i vinte në dritare të ftoheshin, gjithmonë e mbyllte dritaren. Natën e mirë, kuleç udhëtar.$s$
  ]::text[],
  array['classic', 'adventure']::text[], 0, 72, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gkuleciqeiku" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gkuleciqeiku)"/><path d="M8.2 43L18.2 100H-1.8Z" fill="#5F8C76" opacity="0.85"/><path d="M21.3 41.4L31.3 100H11.3Z" fill="#8FB5A0" opacity="0.85"/><path d="M36 51.7L46 100H26Z" fill="#5F8C76" opacity="0.85"/><circle cx="48" cy="76.9" r="15.4" fill="#8FB5A0" opacity="0.85"/><path d="M112 39.4L122 100H102Z" fill="#5F8C76" opacity="0.85"/><path d="M129.1 36L139.1 100H119.1Z" fill="#8FB5A0" opacity="0.85"/><circle cx="143.1" cy="69.1" r="20.6" fill="#8FB5A0" opacity="0.85"/><path d="M0 101.8Q40 95.7 80 101.7T160 98V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><ellipse cx="32" cy="42" rx="20" ry="17" fill="#E7B04B"/><ellipse cx="32" cy="47" rx="18" ry="10" fill="#C98B4A" opacity="0.35"/><circle cx="26" cy="38" r="1.6" fill="#8A5A44"/><circle cx="38" cy="38" r="1.6" fill="#8A5A44"/><path d="M27 45Q32 49 37 45" fill="none" stroke="#8A5A44" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="32" cy="60" rx="22" ry="2" fill="#2C463B" opacity="0.3"/></g></svg>$s$,
  'published', false, 520, 'editor'
),
(
  $s$shtepiza-ne-pyll$s$, 'sq', $s$Shtëpiza në pyll$s$,
  $s$Përrallë popullore ruse: në një shtëpizë të vogël në pyll vijnë të banojnë një mizë, një mi, një bretkosë, një lepur, një dhelpër, një ujk, dhe në fund një ari i madh.$s$,
  array[
    $s$Në mes të një fushe, në skaj të pyllit, ishte një shtëpizë e vogël druri, me një dritare të rrumbullakët e me një oxhak të vogël. Nuk ishte as shumë e madhe, as shumë e vogël. Dhe në të nuk banonte askush.$s$,
    $s$Një ditë, kaloi aty pranë një mizë që fluturonte e lodhur. «Shtëpizë, shtëpizë, kush banon në ty?» pyeti. Askush s'u përgjigj. Miza hyri brenda, u ul pranë dritares dhe tha: «Sa vend i mirë! Do të banoj këtu.» Dhe filloi të jetonte në shtëpizë.$s$,
    $s$Pas pak, erdhi duke vrapuar një mi i vogël gri. «Shtëpizë, shtëpizë, kush banon në ty?» «Unë, miza zukatëse. Po ti, kush je?» «Unë jam miu kruanjës.» «Hyr e bano me mua.» Miu hyri, dhe filluan të jetonin bashkë: miza bënte zzzz te dritarja, miu kruante kokrra gruri në kuzhinë.$s$,
    $s$Pastaj erdhi duke kërcyer një bretkosë e gjelbër. «Shtëpizë, shtëpizë, kush banon në ty?» «Unë, miza zukatëse. Unë, miu kruanjës. Po ti, kush je?» «Unë jam bretkosa kërcyese.» «Hyr e bano me ne.» Bretkosa hyri, dhe tani ishin tre. Bretkosa bëri një pellg të vogël me ujë në një tas dhe rrinte aty, e lumtur.$s$,
    $s$Pastaj erdhi një lepur me veshë të gjatë. «Shtëpizë, shtëpizë, kush banon në ty?» «Unë, miza zukatëse. Unë, miu kruanjës. Unë, bretkosa kërcyese. Po ti, kush je?» «Unë jam lepuri vrapues.» «Hyr e bano me ne.» Dhe tani ishin katër. Lepuri solli karota nga kopshti dhe i ndau me të gjithë.$s$,
    $s$Pastaj erdhi dhelpra, me bishtin e kuq si flakë. «Shtëpizë, shtëpizë, kush banon në ty?» «Unë, miza zukatëse. Unë, miu kruanjës. Unë, bretkosa kërcyese. Unë, lepuri vrapues. Po ti, kush je?» «Unë jam dhelpra e bukur.» «Hyr e bano me ne, por pa dinakëri!» «Pa dinakëri», premtoi dhelpra, dhe hyri. Tani ishin pesë.$s$,
    $s$Pastaj erdhi ujku gri, me hapa të rëndë. «Shtëpizë, shtëpizë, kush banon në ty?» «Unë, miza zukatëse. Unë, miu kruanjës. Unë, bretkosa kërcyese. Unë, lepuri vrapues. Unë, dhelpra e bukur. Po ti, kush je?» «Unë jam ujku gri, që i këndon hënës.» «Hyr e bano me ne, por pa kafshuar!» «Pa kafshuar», premtoi ujku, dhe u fut brenda, pak i ngushtë. Tani ishin gjashtë.$s$,
    $s$Dhe jetonin të gjashtë bashkë. Miza zgjonte të gjithë në mëngjes. Miu fshinte dyshemenë. Bretkosa mbante ujë. Lepuri sillte perime. Dhelpra gatuante supë, se ishte e zonja në kuzhinë. Dhe ujku priste dru e ndizte zjarrin. Shtëpiza ishte e ngushtë, por e ngrohtë dhe plot me këngë.$s$,
    $s$Një mbrëmje, nga pylli doli një ari. Një ari i madh, i madh, me putra si lopata e me zë si bubullimë. «Shtëpizë, shtëpizë, kush banon në ty?» «Unë, miza zukatëse. Unë, miu kruanjës. Unë, bretkosa kërcyese. Unë, lepuri vrapues. Unë, dhelpra e bukur. Unë, ujku gri. Po ti, kush je?» «Unë jam ariu i madh, që i shtyp të gjithë. Më lini të hyj!»$s$,
    $s$«Je shumë i madh», i thanë. «Nuk ke vend.» «Po unë kam ftohtë», tha ariu me zë më të butë. «Dhe jam vetëm.» Kafshët u shikuan njëra me tjetrën. «Atëherë hip në çati», i thanë. «Mbi oxhak është ngrohtë.» Ariu u ngjit në çati dhe u shtri. Por çatia bëri krrr, krrrak, dhe papritur: BUM! Shtëpiza u shemb nën peshën e ariut.$s$,
    $s$Kafshët dolën me vrap nga rrënojat, të gjitha shëndoshë e mirë, me pluhur në qime e me pendët e ngatërruara. Ariu u ul përtokë, i turpëruar, me kokën ulur. «Më falni», tha. «Nuk doja. Doja vetëm të mos isha vetëm.»$s$,
    $s$Kafshët e shikuan ariun e madh e të trishtuar, dhe zemrat iu zbutën. «S'ka gjë», tha miza. «Por tani duhet të na ndihmosh», tha ujku. «Ti je më i forti nga të gjithë», tha lepuri. «Do të ndërtojmë një shtëpi të re», tha dhelpra. «Më të madhe!» thirri bretkosa. «Me vend për të gjithë», tha miu.$s$,
    $s$Dhe kështu bënë. Ariu mbante trungjet e mëdhenj. Ujku dhe dhelpra i rendisnin. Lepuri dhe bretkosa sillnin myshk për të mbyllur të çarat. Miu bënte dritaret, dhe miza tregonte nga lart ku duhej vënë çdo trung. Brenda një jave, në vend të shtëpizës së vogël, ishte një shtëpi e madhe druri, me shtatë dritare e me një oxhak të madh.$s$,
    $s$Dhe tani jetojnë të shtatë bashkë: miza zukatëse, miu kruanjës, bretkosa kërcyese, lepuri vrapues, dhelpra e bukur, ujku gri dhe ariu i madh. Dhe kur ndonjë kafshë tjetër vjen e troket, ata s'pyesin më «kush je?». Vetëm hapin derën dhe thonë: «Hyr, se ka vend.»$s$
  ]::text[],
  array['classic', 'friendship']::text[], 0, 60, 10, 'house',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gshtepizanepyll" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#CBE0D3"/><stop offset="1" stop-color="#EDF3EC"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gshtepizanepyll)"/><circle cx="8.9" cy="70.6" r="19.6" fill="#8FB5A0" opacity="0.85"/><path d="M21.1 48.2L31.1 100H11.1Z" fill="#8FB5A0" opacity="0.85"/><path d="M36.4 59.3L46.4 100H26.4Z" fill="#5F8C76" opacity="0.85"/><circle cx="47.9" cy="69.3" r="20.5" fill="#8FB5A0" opacity="0.85"/><path d="M116.6 53.4L126.6 100H106.6Z" fill="#5F8C76" opacity="0.85"/><path d="M130.5 56.5L140.5 100H120.5Z" fill="#8FB5A0" opacity="0.85"/><path d="M146 57.3L156 100H136Z" fill="#5F8C76" opacity="0.85"/><path d="M0 98.6Q40 96.2 80 102.2T160 100.1V120H0Z" fill="#5F8C76"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><rect x="40" y="12" width="6" height="14" rx="1" fill="#2C463B"/><path d="M43 10Q40 4 44 0" fill="none" stroke="#EDF3EC" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><path d="M8 32L32 12L56 32Z" fill="#2C463B"/><rect x="12" y="30" width="40" height="30" rx="1" fill="#2C463B"/><rect x="18" y="38" width="9" height="9" rx="1.5" fill="#D9644A"/><rect x="36" y="42" width="9" height="18" rx="1.5" fill="#EDF3EC"/><path d="M22.5 38V47M18 42.5H27" fill="none" stroke="#2C463B" stroke-width="1" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 530, 'editor'
),
(
  $s$zogu-qe-kerkonte-folene$s$, 'sq', $s$Zogu që kërkonte folenë$s$,
  $s$Një trumcak i vogël humbet folenë në një stuhi. Gjithë ditën kërkon një vend për të fjetur, derisa gjen një dritare të hapur dhe një vajzë që e pret.$s$,
  array[
    $s$Një natë vjeshte, në një qytet të vogël, fryu një erë e fortë. Shkundi pemët, rrëzoi gjethet dhe çoi larg gjithçka që s'ishte e lidhur mirë. Dhe kur mëngjesi erdhi e era pushoi, një trumcak i vogël kafe u zgjua në një degë dhe pa që foleja e tij ishte zhdukur. Era e kishte marrë me vete, me gjithë degët e kashtat.$s$,
    $s$«Ku do të fle sonte?» pyeti trumcaku i vogël veten. Kishte ftohtë, dhe dielli i vjeshtës ishte i dobët. Vendosi të kërkonte një vend të ri, të ngrohtë e të sigurt, para se të binte nata. Dhe u nis.$s$,
    $s$Së pari, shkoi te pëllumbat, që flinin nën strehën e kishës së vjetër. «A mund të fle me ju sonte?» pyeti. Pëllumbat e shikuan nga lart poshtë. «Këtu ka vend vetëm për pëllumba», thanë. «Dhe jemi shumë të ngushtë.» Trumcaku i vogël i falënderoi dhe vazhdoi.$s$,
    $s$Pastaj shkoi te rosat, që flinin buzë liqenit të parkut, mes kallamave. «A mund të fle me ju?» pyeti. «Sigurisht», tha një rosë e madhe e bardhë. «Por ne flemë në ujë, duke notuar. A di të notosh?» Trumcaku i vogël shikoi ujin e ftohtë e të errët dhe tundi kokën. «Jo.» «Atëherë më vjen keq», tha rosa me mirësi.$s$,
    $s$Shkoi te bufi, që jetonte në një vrimë të një peme të madhe në park. «A mund të fle me ty?» Bufi hapi një sy të madh të verdhë. «Mund të vish», tha, «por unë rri zgjuar gjithë natën dhe fle gjithë ditën. Dhe flas shumë natën. Hu-hu, hu-hu.» Trumcaku i vogël mendoi që s'do të flinte dot me gjithë ato hu-hu dhe vazhdoi rrugën.$s$,
    $s$Dielli filloi të ulej pas çative. Qielli u bë portokalli, pastaj rozë, pastaj gri. Trumcaku i vogël ishte lodhur shumë. Krahët i ishin bërë të rëndë dhe kishte ftohtë në këmbë. U ul mbi parvazin e një dritareje, në katin e dytë të një shtëpie të verdhë, që të pushonte pak. Dhe pa që dritarja ishte pak e hapur, dhe nga brenda dilte një dritë e ngrohtë.$s$,
    $s$Brenda, një vajzë e vogël me flokë të kuq po vishte pizhamat. Quhej Mira. Kur pa trumcakun e vogël në parvaz, ndaloi dhe ngriu, që të mos e trembte. «Përshëndetje, zog i vogël», pëshpëriti. «Pse je këtu kaq vonë? Ku e ke shtëpinë?» Trumcaku i vogël nuk dinte të fliste gjuhën e njerëzve, por bëri një cicërimë të vogël e të trishtuar.$s$,
    $s$Mira u mendua. Pastaj vrapoi te dollapi dhe nxori një kuti të vogël kartoni, nga ato të këpucëve. Brenda vuri një shami të vjetër leshi, të butë e të ngrohtë. Bëri një vrimë të rrumbullakët në njërën anë të kutisë, që të ishte si një derë. Pastaj e vendosi kutinë në parvaz, jashtë dritares, por nën strehë, ku s'arrinte shiu.$s$,
    $s$Pastaj Mira vuri pranë kutisë një kapak kavanozi me pak ujë, dhe disa thërrime buke dhe fara luledielli që i kishte mbetur nga ushqimi i papagallit të gjyshes. Dhe u tërhoq pas perdes, me shumë durim, për të parë.$s$,
    $s$Trumcaku i vogël e shikoi kutinë me dyshim. Shkoi te vrima, futi kokën brenda, e nxori. E futi përsëri. Pastaj, ngadalë, hyri i tëri. Brenda ishte ngrohtë, e butë, me erë leshi e me erë shtëpie. Era nuk hynte dot. U rrotullua dy herë mbi shaminë, siç bëjnë zogjtë kur rregullojnë folenë, dhe u ul. Pastaj doli përsëri, hëngri disa fara luledielli, piu pak ujë dhe u kthye brenda.$s$,
    $s$Mira buzëqeshi pas perdes. Pastaj u fut në shtrat dhe mamaja i fiku dritën. «A ka gjetur ku të flejë zogu yt?» pyeti mamaja. «Po», tha Mira. «I bëra një shtëpi.» Mamaja e puthi. «Atëherë fli e qetë. Ke bërë një gjë shumë të mirë sot.»$s$,
    $s$Atë natë, era u ngrit përsëri pak, por trumcaku i vogël nuk e ndjeu. Ishte në folenë e tij të re, e ngrohtë e e sigurt, me kokën nën krah. Dhe në anën tjetër të xhamit, Mira flinte në shtratin e saj, edhe ajo e ngrohtë e e sigurt. Dy fole, njëra pranë tjetrës, në të njëjtën dritare.$s$,
    $s$Në mëngjes, Mira u zgjua nga një cicërimë. Trumcaku ishte në parvaz dhe i këndonte, sikur i thoshte faleminderit. Gjatë gjithë dimrit, ai fjeti në kutinë e kartonit, dhe çdo mëngjes këndonte te dritarja e Mirës. Dhe në pranverë, kur ndërtoi një fole të re në pemën e oborrit, me një trumcake tjetër, vinte ende çdo mëngjes t'i këndonte. Natën e mirë, zog i vogël. Natën e mirë, Mira.$s$
  ]::text[],
  array['sleep', 'nature', 'friendship']::text[], 0, 72, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gzoguqekerkontefolene" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E3A08A"/><stop offset="1" stop-color="#F6D6BD"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gzoguqekerkontefolene)"/><circle cx="27.7" cy="80" r="22" fill="#FFF1DE" opacity="0.8"/><path d="M40.6 30l4 3l4 -3M113 24l3 2.4l3 -2.4" fill="none" stroke="#B47266" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><path d="M0 91.6Q40 76.6 80 88.6T160 87.6V120H0Z" fill="#D2917E"/><path d="M0 103.3Q40 93 80 101T160 103.1V120H0Z" fill="#B47266"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M4 52Q32 46 62 50" fill="none" stroke="#8A5A44" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><ellipse cx="56" cy="46" rx="4" ry="2" fill="#7DA86B" transform="rotate(-20 56 46)"/><path d="M20 40L4 44L9 36Z" fill="#FFF5E8"/><ellipse cx="30" cy="38" rx="14" ry="10" fill="#FFF5E8" transform="rotate(-12 30 38)"/><circle cx="42" cy="30" r="7" fill="#FFF5E8"/><path d="M48 29L55 30.5L48 32Z" fill="#7A3E3A"/><path d="M24 36Q32 32 38 38Q30 42 24 36Z" fill="#C98673" opacity="0.35"/><circle cx="44" cy="28.5" r="1.4" fill="#C98673"/><path d="M30 47L29 51M34 47L34 51" fill="none" stroke="#7A3E3A" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
