(
  $s$pula-e-kuqe$s$, 'sq', $s$Pula e kuqe dhe kokrrat e grurit$s$,
  $s$Përrallë popullore angleze: pula e kuqe gjen disa kokrra gruri dhe pyet kush do ta ndihmojë t'i mbjellë, t'i korrë e t'i bëjë bukë. Askush s'ka kohë, deri kur vjen ora e ngrënies.$s$,
  array[
    $s$Në një fermë të vogël, me një hambar të kuq e me një pemë të madhe arre në mes të oborrit, jetonte një pulë e kuqe. Ishte e vogël, e zellshme dhe gjithmonë me diçka për të bërë. Në të njëjtën fermë jetonin edhe një mace e përgjumur, një qen dembel dhe një rosë që s'pushonte së foluri.$s$,
    $s$Një mëngjes, ndërsa gërmonte në oborr, pula e kuqe gjeti disa kokrra gruri, të verdha e të forta. «Shikoni!» thirri. «Kush do të më ndihmojë t'i mbjell këto kokrra?» «Jo unë», tha maca, duke u shtrirë në diell. «Jo unë», tha qeni, duke mbyllur sytë. «Jo unë», tha rosa, «se kam shumë për të folur.» «Mirë», tha pula e kuqe. «Do t'i mbjell vetë.» Dhe kështu bëri.$s$,
    $s$Gruri mbiu. Fillimisht, si fije të holla jeshile. Pastaj u rrit, gjithnjë e më i lartë, gjatë gjithë pranverës. Por pastaj barërat e këqija filluan të rriteshin rreth tij. «Kush do të më ndihmojë të heq barërat e këqija?» pyeti pula. «Jo unë», tha maca. «Jo unë», tha qeni. «Jo unë», tha rosa. «Mirë», tha pula e kuqe. «Do t'i heq vetë.» Dhe kështu bëri, çdo mëngjes, nën diellin e nxehtë.$s$,
    $s$Erdhi vera, dhe gruri u bë i artë, me kallinj të rëndë që lëkundeshin në erë. «Kush do të më ndihmojë ta korr grurin?» pyeti pula e kuqe. «Jo unë», tha maca, e cila po luante me një fije peri. «Jo unë», tha qeni, i cili po kruhej pas gardhit. «Jo unë», tha rosa, «se nuk kam kohë.» «Mirë», tha pula e kuqe. «Do ta korr vetë.» Dhe e korri, kalli pas kalli, gjithë ditën.$s$,
    $s$«Kush do të më ndihmojë ta shirë grurin, që të ndaj kokrrat nga kashta?» «Jo unë.» «Jo unë.» «Jo unë.» «Mirë, do ta shir vetë.» Dhe e shiu, duke e rrahur me një shkop të vogël, deri sa kokrrat ranë si shi i artë mbi pëlhurë.$s$,
    $s$«Kush do të më ndihmojë ta çoj grurin te mulliri, që ta bëj miell?» «Jo unë.» «Jo unë.» «Jo unë.» «Mirë, do ta çoj vetë.» Dhe e mbushi grurin në një thes, e ngarkoi në një karrocë të vogël dhe e tërhoqi deri te mulliri, larg, pranë lumit. Kur u kthye në mbrëmje, ishte e lodhur, por thesi ishte plot me miell të bardhë e të butë.$s$,
    $s$«Dhe tani», tha pula e kuqe, «kush do të më ndihmojë ta bëj miellin bukë?» «Jo unë», tha maca. «Jo unë», tha qeni. «Jo unë», tha rosa. «Mirë», tha pula e kuqe. «Do ta bëj vetë.» Dhe e gatoi brumin, e la të vinte, i dha formë, e futi në furrë.$s$,
    $s$Pas pak, nga furra filloi të dilte një erë e mrekullueshme. Era e bukës së ngrohtë përhapej nëpër oborr, mbi gardh, deri te hambari. Maca hapi një sy. Qeni ngriti hundën. Rosa pushoi së foluri. Dhe kur pula e kuqe nxori nga furra një bukë të madhe e të artë, me kore kërcitëse, të tre ishin aty, te dera e kuzhinës.$s$,
    $s$«Kush do të më ndihmojë ta ha bukën?» pyeti pula e kuqe. «Unë!» tha maca. «Unë!» tha qeni. «Unë, unë, unë!» tha rosa. Pula e kuqe i vështroi gjatë, me kokën anash. «Kur ju kërkova ndihmë për ta mbjellë, s'kishit kohë. Për ta korrur, s'kishit kohë. Për ta bërë bukë, s'kishit kohë. Dhe tani të gjithë keni kohë për ta ngrënë?»$s$,
    $s$Maca uli kokën. Qeni uli bishtin. Rosa, për herë të parë në jetën e saj, nuk tha asnjë fjalë. Pula e kuqe e hëngri një fetë të bukës, e ngrohtë dhe e shijshme, me zogjtë e saj të vegjël, ndërsa të tjerët shikonin.$s$,
    $s$Por pula e kuqe kishte zemër të mirë. Pasi u ngop, e preu bukën që mbeti në tri copa dhe ua dha macës, qenit e rosës. «Kësaj radhe», tha, «po jua jap. Por pranverën tjetër, kur të mbjell grurin, dua t'ju shoh në arë.»$s$,
    $s$Dhe pranverën tjetër, kur pula e kuqe gjeti përsëri kokrra gruri dhe pyeti «Kush do të më ndihmojë?», ndodhi një mrekulli e vogël. «Unë!» tha maca. «Unë!» tha qeni. «Unë, unë, unë!» tha rosa. Dhe atë vit, puna u bë katër herë më shpejt, buka doli katër herë më e madhe, dhe u hëngër nga të katër, nën pemën e arrës, me këngë e me të qeshura.$s$
  ]::text[],
  array['classic', 'lessons']::text[], 0, 72, 9, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gpulaekuqe" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gpulaekuqe)"/><circle cx="37.3" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 82.7Q40 77.3 80 89.3T160 89.5V120H0Z" fill="#B5D39A"/><path d="M0 97Q40 88.5 80 96.5T160 99.3V120H0Z" fill="#93BE7B"/><circle cx="132.9" cy="106.6" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="115.7" cy="104.1" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="17.1" cy="107" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="11.7" cy="107.5" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="6.4" cy="114.5" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="148.2" cy="105.5" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="33.2" cy="110.9" r="1.6" fill="#E7B04B" opacity="0.9"/><circle cx="29.7" cy="106.7" r="1.6" fill="#E58C8A" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M18 38Q8 30 10 22Q16 30 22 32Z" fill="#3E5A38"/><circle cx="28" cy="42" r="14" fill="#3E5A38"/><path d="M34 34L40 22L48 24L44 38Z" fill="#3E5A38"/><circle cx="44" cy="22" r="7" fill="#3E5A38"/><path d="M50 21L57 23L50 25Z" fill="#E58C5A"/><circle cx="41" cy="15" r="2.6" fill="#E58C5A"/><circle cx="45" cy="14" r="2.6" fill="#E58C5A"/><circle cx="46" cy="20" r="1.4" fill="#F4F7EA"/><path d="M24 55L24 60M32 55L32 60" fill="none" stroke="#E58C5A" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></g></svg>$s$,
  'published', false, 580, 'editor'
),
(
  $s$shtepia-e-breshkes$s$, 'sq', $s$Breshka që e mbante shtëpinë me vete$s$,
  $s$Breshka Tina s'ka frikë të flejë kudo, sepse e mban shtëpinë në shpinë. Por një natë, ajo mëson se shtëpia nuk është vetëm një guaskë.$s$,
  array[
    $s$Breshka Tina ishte shumë krenare për shtëpinë e saj. Ishte e fortë, e rrumbullakët, me pllaka kafe e të verdha si një mozaik, dhe e mbante gjithmonë në shpinë. «Unë s'kam nevojë të kthehem në shtëpi në mbrëmje», u thoshte kafshëve të tjera të kopshtit. «Ku të jem, aty kam shtëpinë. Fus kokën brenda dhe fle.»$s$,
    $s$Kafshët e tjera e kishin pak zili. Lepuri duhej të vraponte në strofullën e tij para se të errësohej. Iriqi duhej të kthehej te grumbulli i gjetheve. Zogjtë duhej të fluturonin në fole. Por Tina mund të flinte kudo: nën domate, pranë lules së diellit, mes barit të gjatë. Thjesht fuste kokën, këmbët e bishtin në guaskë, dhe natën e mirë.$s$,
    $s$Një mbrëmje, Tina vendosi të bënte një shëtitje të gjatë. Doli nga kopshti i saj, nën gardh, dhe eci, ngadalë, shumë ngadalë, siç ecin breshkat, deri në fund të fushës, ku s'kishte qenë kurrë. Kaloi pranë një përroi, pranë disa gurëve të mëdhenj, pranë një peme të vjetër dardhe. Dhe kur u bë errët, u ndal. «Këtu do të fle sonte», tha me krenari.$s$,
    $s$Futi kokën në guaskë. Futi këmbët. Futi bishtin. Dhe priti gjumin. Por gjumi nuk erdhi. Brenda guaskës ishte errët e e qetë si gjithmonë, por diçka nuk shkonte. Tina nxori pak kokën dhe shikoi përreth. Nuk njihte asgjë. Pema e dardhës bënte hije të çuditshme. Përroi bënte zhurma që s'i kishte dëgjuar kurrë. Dhe s'kishte asnjë mik pranë.$s$,
    $s$Në kopshtin e saj, Tina dëgjonte çdo natë zërat e njohura: lepurin që gërmonte në strofull para gjumit, iriqin që gërhiste nën gjethe, bretkosën e pellgut që këndonte kroak-kroak, zogjtë që cicëronin butë në fole. Por këtu, larg, s'kishte asnjë zë të njohur. Vetëm era dhe errësira.$s$,
    $s$Tina e futi përsëri kokën në guaskë. «Kam shtëpinë me vete», i tha vetes. «S'kam pse të kem frikë.» Por ndjeu një gjë të vogël e të ftohtë në zemër. Ndjeu mall. Mall për domatet, për lulen e diellit, për lepurin, për iriqin, për bretkosën e pellgut. Dhe kuptoi diçka që s'e kishte kuptuar kurrë: shtëpia nuk ishte vetëm guaska.$s$,
    $s$Ndërkohë, në kopsht, lepuri kishte vënë re që Tina nuk ishte në vendin e saj, nën domate. «Ku është Tina?» pyeti iriqin. «Nuk e di», tha iriqi, i shqetësuar. «S'e kam parë që nga dreka.» Pyetën bretkosën. Pyetën zogjtë. Askush s'e kishte parë. Dhe kafshët e kopshtit, edhe pse ishte natë, vendosën ta kërkonin.$s$,
    $s$Bufi, që rrinte zgjuar natën, fluturoi i pari mbi fushë. «Hu-hu! Tina! Tina!» Lepuri vraponte nëpër bar, duke nuhatur. Iriqi ecte ngadalë, duke dëgjuar me veshët e tij të vegjël. Dhe xixëllonjat, që e kishin dëgjuar lajmin, fluturonin para tyre si fenerë të vegjël, duke ndriçuar rrugën.$s$,
    $s$Tina, brenda guaskës, dëgjoi një zë nga larg. «Hu-hu! Tina!» Nxori kokën. Pa dritat e vogla të xixëllonjave që afroheshin. Dhe pastaj pa lepurin, me veshët e gjatë që i dridheshin, dhe iriqin, të lodhur e të pluhurosur. «Tina!» thirri lepuri. «Ja ku je! Ç'po bën kaq larg?»$s$,
    $s$«Desha të flija kudo», tha Tina, me zë pak të turpëruar. «Mendoja se shtëpia ime është vetëm guaska. Por më mungonit ju.» Iriqi buzëqeshi. «Edhe ti na mungove», tha. «Kopshti s'është i njëjti pa ty nën domate.» Dhe të gjithë bashkë, me xixëllonjat që ndriçonin rrugën e me bufin që fluturonte sipër, u kthyen ngadalë drejt kopshtit. Shumë ngadalë, sepse ecnin me hapat e Tinës.$s$,
    $s$Kur arritën në kopsht, ishte vonë, shumë vonë. Tina shkoi në vendin e saj, nën domate. Lepuri u fut në strofull, por e la kokën jashtë, pranë saj. Iriqi u shtri nën gjethe, pak më afër se zakonisht. Bretkosa këndoi një kroak-kroak të butë, si ninullë. Dhe zogjtë cicëruan një herë të fundit nga foleja.$s$,
    $s$Tina futi kokën në guaskë. Dhe këtë herë, gjumi erdhi menjëherë, i ngrohtë e i butë. Sepse tani e dinte. Guaska ishte shtëpia e trupit të saj. Por shtëpia e zemrës së saj ishte këtu: nën domate, pranë miqve, në vendin ku të tjerët vinin ta kërkonin kur humbiste. Natën e mirë, Tina. Natën e mirë, kopsht.$s$
  ]::text[],
  array['sleep', 'friendship']::text[], 0, 72, 9, 'turtle',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gshtepiaebreshkes" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#D3E8CB"/><stop offset="1" stop-color="#F4F7EA"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gshtepiaebreshkes)"/><circle cx="39.8" cy="22" r="10" fill="#FFF3D6"/><ellipse cx="118" cy="26" rx="14" ry="5" fill="#FFFFFF" opacity="0.85"/><circle cx="114" cy="22" r="6" fill="#FFFFFF" opacity="0.85"/><circle cx="123" cy="21" r="5" fill="#FFFFFF" opacity="0.85"/><path d="M0 85.2Q40 74.5 80 86.5T160 83.9V120H0Z" fill="#B5D39A"/><path d="M0 101.2Q40 92.8 80 100.8T160 100.3V120H0Z" fill="#93BE7B"/><circle cx="13.7" cy="110.8" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="123.2" cy="109.7" r="1.6" fill="#E58C8A" opacity="0.9"/><circle cx="146.9" cy="110.9" r="1.6" fill="#FFFFFF" opacity="0.9"/><circle cx="39.2" cy="108.6" r="1.6" fill="#E58C8A" opacity="0.9"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M10 46Q12 26 32 26Q52 26 54 46Z" fill="#3E5A38"/><path d="M22 30L26 38L38 38L42 30M26 38L22 46M38 38L42 46" fill="none" stroke="#F4F7EA" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><circle cx="58" cy="42" r="6" fill="#3E5A38"/><circle cx="60" cy="40" r="1.1" fill="#F4F7EA"/><ellipse cx="16" cy="50" rx="4" ry="3" fill="#3E5A38"/><ellipse cx="46" cy="50" rx="4" ry="3" fill="#3E5A38"/><path d="M10 44L4 46L10 48Z" fill="#3E5A38"/></g></svg>$s$,
  'published', false, 590, 'editor'
),
(
  $s$supa-me-gur$s$, 'sq', $s$Supa me gur$s$,
  $s$Përrallë popullore evropiane: një udhëtar i uritur arrin në një fshat ku askush s'ndan asgjë, dhe me vetëm një gur e një kazan i mëson të gjithë të gatuajnë bashkë.$s$,
  array[
    $s$Një mbrëmje vjeshte, në një fshat të vogël mes kodrave, arriti një udhëtar. Kishte ecur gjithë ditën, kishte këpucë të pluhurosura, një thes të vjetër në shpinë dhe një kazan bakri të varur pas tij. Ishte i lodhur dhe i uritur, dhe mendoi se në fshat do të gjente diçka për të ngrënë.$s$,
    $s$Trokiti në derën e parë. «Mirëmbrëma. A keni pak bukë për një udhëtar të uritur?» «Jo», tha gruaja që hapi derën. «Viti ka qenë i vështirë. S'kemi as për veten.» Dhe e mbylli derën. Trokiti në derën e dytë, në të tretën, në të katërtën. Kudo e njëjta përgjigje. Njerëzit e fshatit kishin frikë se nuk do t'u mjaftonte, ndaj fshihnin gjithçka që kishin.$s$,
    $s$Udhëtari buzëqeshi. Shkoi në sheshin e fshatit, pranë kroit, mblodhi disa dru dhe ndezi zjarr. Pastaj mbushi kazanin me ujë nga kroi, e vuri mbi zjarr, dhe nga xhepi nxori një gur të rrumbullakët, gri e të lëmuar. E lau me kujdes dhe e futi në kazan, ku uji filloi të ziente.$s$,
    $s$Fëmijët e fshatit, kuriozë, u afruan të parët. «Çfarë po gatuan?» e pyeti një djalë i vogël. «Supë me gur», tha udhëtari, duke e përzier ujin me një lugë të gjatë druri. «Është supa më e shijshme në botë. Ma ka mësuar gjyshi im.» «Supë me gur?» pyeti një vajzë me habi. «Si mund të bëhet supë me një gur?» «Do ta shohësh», tha udhëtari.$s$,
    $s$Pas pak, u afruan edhe të rriturit, të habitur nga zjarri në mes të sheshit. Udhëtari provoi supën me lugë dhe psherëtiu me kënaqësi. «Mmm, shumë e mirë. Por me pak kripë do të ishte edhe më e mirë.» «Unë kam pak kripë», tha një grua. «Vetëm një grusht.» Shkoi në shtëpi dhe solli kripë. Udhëtari e hodhi në kazan.$s$,
    $s$E provoi përsëri. «Shumë e mirë. Por me një qepë, do të ishte e mrekullueshme. Gjyshi im gjithmonë hidhte një qepë.» «Unë kam një qepë», tha një burrë. «E kam fshehur në qilar.» Dhe solli qepën. Udhëtari e qëroi, e preu dhe e hodhi në kazan. Era e supës filloi të përhapej nëpër shesh.$s$,
    $s$«Ah», tha udhëtari. «Kjo është pothuajse si supa e gjyshit. Vetëm se ai hidhte edhe disa karota.» «Unë kam karota!» thirri një vajzë dhe vrapoi te shtëpia. «Dhe unë kam patate», tha një plak. «Dhe unë kam pak lakër», tha një tjetër. «Dhe unë kam fasule të thata.» «Dhe unë, një copë mish.» «Dhe unë, ca gjethe selino nga kopshti.»$s$,
    $s$Njëri pas tjetrit, fshatarët shkuan në shtëpitë e tyre dhe sollën diçka: pak nga kjo, pak nga ajo. Asnjëri s'solli shumë, sepse askush s'kishte shumë. Por bashkë, kazani u mbush aq shumë, sa udhëtari duhej ta përziente me të dyja duart. Dhe era e supës ishte bërë aq e mirë, sa njerëzit filluan të sillnin edhe tasa e lugë.$s$,
    $s$Dikush solli bukë misri. Dikush solli djathë. Dikush solli ca mollë nga pema e oborrit. Dikush nxori një tryezë të gjatë në shesh. Dhe dikush tjetër, që kishte një fyell, filloi t'i binte një kënge të vjetër. Sheshi i fshatit, që ishte i heshtur e i errët kur arriti udhëtari, tani ishte plot me dritë, me zëra e me të qeshura.$s$,
    $s$Kur supa ishte gati, udhëtari e ndau në tasa: për pleqtë, për fëmijët, për gratë e për burrat, për të gjithë. Dhe u mjaftoi të gjithëve, madje edhe për të dytën herë. Ishte supa më e shijshme që kishin ngrënë ndonjëherë.$s$,
    $s$«Kjo supë me gur», tha plaku me patate, duke fshirë mustaqet, «është me të vërtetë e mrekullueshme. Si mund të bëhet kaq e mirë vetëm me një gur?» Udhëtari buzëqeshi dhe nxori gurin nga fundi i kazanit. E fshiu dhe e ngriti lart, që ta shihnin të gjithë.$s$,
    $s$«Guri nuk ka bërë asgjë», tha. «Supën e bëtë ju. Secili prej jush solli pak, dhe pak e pak bëhet shumë. Kur secili ruan vetëm për veten, të gjithë mbeten të uritur. Kur secili ndan pak, të gjithë hanë.»$s$,
    $s$Fshatarët heshtën, pastaj filluan të qeshnin, të turpëruar e të gëzuar njëkohësisht. Atë natë, udhëtari fjeti në shtëpinë e gruas që i kishte mbyllur derën e para, në një shtrat të ngrohtë, me një jorgan të trashë. Dhe të nesërmen në mëngjes, kur u nis përsëri në rrugë, ia la gurin djalit të vogël. «Mbaje», i tha. «Dhe kur fshati të harrojë, bëni përsëri supë me gur.»$s$
  ]::text[],
  array['classic', 'friendship']::text[], 36, 96, 10, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gsupamegur" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E8D5C0"/><stop offset="1" stop-color="#F6EBDD"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gsupamegur)"/><path d="M-4 96V59.5L8.7 51.5L21.4 59.5V96Z" fill="#D6BB9F"/><rect x="6.7" y="65.5" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><path d="M22.4 96V58.4L32.7 50.4L43 58.4V96Z" fill="#D6BB9F"/><rect x="30.7" y="64.4" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><path d="M114.5 96V72L126.7 64L139 72V96Z" fill="#C29F80"/><rect x="124.7" y="78" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><path d="M140 96V72.8L147.2 64.8L154.4 72.8V96Z" fill="#C29F80"/><rect x="145.2" y="78.8" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><path d="M155.4 96V61.1L168.3 53.1L181.3 61.1V96Z" fill="#D6BB9F"/><rect x="166.3" y="67.1" width="4" height="5" rx="1" fill="#E7B04B" opacity="0.8"/><circle cx="33.6" cy="20" r="8" fill="#FFF3D6"/><rect x="0" y="96" width="160" height="24" rx="0" fill="#C29F80"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><path d="M10 30H54Q56 54 32 56Q8 54 10 30Z" fill="#5E4232"/><rect x="6" y="26" width="52" height="6" rx="3" fill="#5E4232"/><path d="M18 56L16 60M46 56L48 60" fill="none" stroke="#5E4232" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><path d="M24 22Q20 14 24 6M34 22Q30 14 34 6M44 22Q40 14 44 6" fill="none" stroke="#5E4232" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" opacity="0.5"/><ellipse cx="32" cy="29" rx="6" ry="2.4" fill="#F6EBDD" opacity="0.6"/></g></svg>$s$,
  'published', false, 600, 'editor'
),
(
  $s$fyelli-i-bariut$s$, 'sq', $s$Fyelli i gjyshit$s$,
  $s$Drita del për herë të parë vetë me dhentë në bjeshkë. Kur zbret mjegulla, i ndihmon vetëm melodia e vjetër e fyellit të gjyshit.$s$,
  array[
    $s$Çdo verë, Drita shkonte me gjyshin në bjeshkë, në stanin prej guri ku dhentë kalonin muajt e nxehtë. Lart, bari ishte i butë e i gjelbër, uji rridhte i ftohtë nga borë e shkrirë, dhe natën yjet dukeshin aq afër, sa të dukej se mund t'i kapje me dorë.$s$,
    $s$Gjyshi kishte një fyell druri, të vjetër e të errët, që e kishte marrë nga babai i tij. Sa herë që i binte, dhentë ngrinin kokat dhe vinin pas tij, njëra pas tjetrës, si të ishin magjepsur. «Ato e njohin këtë këngë që kur kanë lindur», thoshte gjyshi. «Për to, kjo këngë do të thotë shtëpi.»$s$,
    $s$Drita donte shumë ta mësonte. Gjyshi i tregonte me durim: ku të vinte gishtat, si të frynte, jo shumë fort, jo shumë lehtë, si frymë e ngrohtë në një mëngjes të ftohtë. Në fillim fyelli bënte vetëm fishkëllima të çuditshme, dhe Drita qeshte bashkë me gjyshin. Por ditë pas dite, melodia filloi të dilte, e plotë dhe e qartë.$s$,
    $s$Një mëngjes, gjyshi u zgjua me dhimbje në këmbë. «Sot s'mund të ngjitem dot», i tha Dritës. «A mund t'i çosh ti dhentë në lëndinën e burimit? Është afër, pas kodrës. Mbaj fyellin me vete. Kur të jetë koha të ktheheni, i bie këngës sonë.»$s$,
    $s$Drita ndjeu krenari dhe pak frikë njëkohësisht. Mori shkopin e vogël, vuri fyellin në brez dhe u nis me dyzet delet dhe qengjat. Qeni i stanit, Murrani, i shkonte pas, duke tundur bishtin. Lëndina e burimit ishte e mbushur me lule të verdha, dhe dhentë kullotën të qeta gjithë mëngjesin, ndërsa Drita numëronte retë.$s$,
    $s$Pas dreke, qielli ndryshoi. Nga majat e maleve filloi të zbriste një mjegull e bardhë, e dendur si leshi i sapolarë. Në pak minuta, Drita s'shihte më as burimin, as kodrën, as delet. Dëgjonte vetëm këmborët që tingëllonin, një këtu, një atje, gjithnjë e më larg. Zemra filloi t'i rrihte fort.$s$,
    $s$Murrani u afrua dhe i fërkoi kokën pas dorës. Drita mori frymë thellë, ashtu si i kishte mësuar gjyshi: një herë, dy herë, tri herë. Pastaj nxori fyellin nga brezi. Gishtat i dridheshin pak, por i vuri në vrima siç duhej. Dhe filloi t'i binte këngës së gjyshit.$s$,
    $s$Melodia u përhap nëpër mjegull, e hollë dhe e ngrohtë. Për një çast, asgjë. Pastaj, nga e majta, një këmborë u afrua. Doli nga mjegulla një dele e bardhë, pastaj një tjetër, pastaj një qengj që vraponte e kërcente. Drita vazhdoi t'i binte, dhe dhentë vinin njëra pas tjetrës, duke u mbledhur rreth saj, si fëmijët rreth zjarrit.$s$,
    $s$Kur i numëroi, ishin tridhjetë e nëntë. Mungonte një, delja laramane me një vesh të zi. Drita i ra edhe një herë këngës, më fort, me gjithë zemër. Dhe nga larg, nga ana e burimit, dëgjoi një blegërimë të vogël. Murrani u nis me vrap në atë drejtim dhe pas pak u kthye duke e shtyrë delen laramane me hundë.$s$,
    $s$«Dyzet», pëshpëriti Drita. Pastaj u nis drejt stanit, duke i rënë fyellit gjatë gjithë rrugës, me dhentë pas saj dhe Murranin në fund të tufës. Mjegulla nisi të hollohej, dhe në fund të saj u duk stani, me tym që dilte nga oxhaku. Te dera rrinte gjyshi, i mbështetur në shkop. E kishte dëgjuar këngën nga larg.$s$,
    $s$«E dija që do t'ia dilje», tha gjyshi, dhe e përqafoi fort. «Kur dëgjova fyellin, e kuptova se dhentë ishin me ty. Dhe ti ishe me to.»$s$,
    $s$Atë mbrëmje, pranë zjarrit, gjyshi i dha Dritës fyellin. «Tani është i yti», i tha. «Ashtu siç ma dha mua babai im.» Drita e mbajti fort në gji. Jashtë, dhentë flinin në vathë, të ngrohta pranë njëra-tjetrës, dhe yjet dolën një nga një mbi bjeshkë.$s$,
    $s$Drita i ra fyellit edhe një herë të fundit, shumë butë, si për t'u uruar natën e mirë deleve. Pastaj u shtri pranë zjarrit, mbylli sytë dhe e zuri gjumi, me melodinë që ende i tingëllonte në vesh. Natën e mirë, Dritë. Natën e mirë, dyzet dele.$s$
  ]::text[],
  array['sleep', 'nature', 'adventure']::text[], 36, 96, 9, 'lamb',
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gfyelliibariut" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#E3A08A"/><stop offset="1" stop-color="#F6D6BD"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gfyelliibariut)"/><circle cx="132.5" cy="80" r="22" fill="#FFF1DE" opacity="0.8"/><path d="M30.5 30l4 3l4 -3M121.1 24l3 2.4l3 -2.4" fill="none" stroke="#B47266" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round" opacity="0.7"/><path d="M0 83.2Q40 78.1 80 90.1T160 91.1V120H0Z" fill="#D2917E"/><path d="M0 100Q40 92.5 80 100.5T160 96.3V120H0Z" fill="#B47266"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 33) scale(1.15)"><circle cx="18" cy="38" r="9" fill="#FFF5E8"/><circle cx="28" cy="33" r="10" fill="#FFF5E8"/><circle cx="38" cy="35" r="9" fill="#FFF5E8"/><circle cx="24" cy="44" r="9" fill="#FFF5E8"/><circle cx="36" cy="44" r="9" fill="#FFF5E8"/><circle cx="14" cy="44" r="7" fill="#FFF5E8"/><ellipse cx="50" cy="37" rx="6" ry="8" fill="#7A3E3A" transform="rotate(20 50 37)"/><ellipse cx="46" cy="31" rx="3.5" ry="2" fill="#7A3E3A" transform="rotate(-20 46 31)"/><circle cx="51.5" cy="35" r="1.1" fill="#C98673"/><rect x="18" y="50" width="4" height="10" rx="2" fill="#7A3E3A"/><rect x="34" y="50" width="4" height="10" rx="2" fill="#7A3E3A"/></g></svg>$s$,
  'published', false, 610, 'editor'
),
(
  $s$vellai-i-vogel$s$, 'sq', $s$Vëllai i vogël$s$,
  $s$Kur në shtëpi vjen një foshnjë, Sara nuk e di nëse i pëlqen. Të gjithë flasin vetëm për të, dhe ai vetëm qan e fle. Derisa një natë, ai i kap gishtin dhe s'ia lëshon më.$s$,
  array[
    $s$Për muaj të tërë, barku i mamasë së Sarës u rrit, u rrit, deri sa u bë i rrumbullakët si një top i madh plazhi. «Aty brenda është vëllai yt», i thoshte mamaja. «Së shpejti do ta njohësh.» Sara vinte veshin te barku dhe ndonjëherë ndjente një shkelm të vogël. «Po luan futboll», thoshte ajo, dhe qeshnin të dy.$s$,
    $s$Pastaj një natë, mamaja dhe babai shkuan me nxitim në spital, dhe Sara mbeti me gjyshen. Kur u kthyen, pas dy ditësh, mamaja kishte në krahë një paketë të vogël, të mbështjellë me një batanije blu. Brenda ishte një foshnjë e vogël, e kuqe, me sy të mbyllur e me grushte të vegjël. «Ky është Lumi», tha mamaja. «Vëllai yt.»$s$,
    $s$Sara e shikoi Lumin. Ishte shumë i vogël. Nuk fliste, nuk luante, nuk qeshte. Vetëm flinte, hante dhe qante. Dhe kur qante, qante shumë fort, me një zë që s'të linte të mendoje për asgjë tjetër. «Kur do të luajë me mua?» pyeti Sara. «Kur të rritet pak», tha babai. «Tani është shumë i vogël.»$s$,
    $s$Ditët kaluan, dhe Sara filloi të ndjente diçka të çuditshme. Kur vinin miqtë e familjes, të gjithë donin të shihnin Lumin. «Oh, sa i bukur!» «Sa i vogël!» «I ngjan babait!» Dhe askush s'e pyeste Sarën për vizatimin e saj të ri, ose për dhëmbin që i lëvizte. Kur mamaja ushqente Lumin, s'mund t'i lexonte Sarës përrallën. Kur babai e tundte Lumin, s'mund të luante me të në oborr.$s$,
    $s$Një mbrëmje, Sara u fut në dhomën e saj dhe s'doli për darkë. Mamaja erdhi dhe e gjeti të ulur në qoshe, me ariun e saj në krahë. «Ç'ke, zemër?» e pyeti. Sara nuk u përgjigj për një kohë të gjatë. Pastaj, me zë të vogël, tha: «Ti s'më do më si më parë. Tani do vetëm Lumin.»$s$,
    $s$Mamaja u ul pranë saj në dysheme dhe e mori në prehër, ashtu si e merrte kur ishte e vogël. «Dëgjo, Sara», i tha. «A e di sa zemra kam unë?» Sara tundi kokën. «Një», tha mamaja. «Por zemra e një nëne është e çuditshme. Kur vjen një fëmijë i ri, ajo nuk ndahet në dysh. Rritet. Bëhet dy herë më e madhe. Dashuria për ty nuk u bë më e vogël kur erdhi Lumi. Është po aq e madhe sa ishte, dhe tani ka edhe një dashuri tjetër pranë saj.»$s$,
    $s$«Po pse merresh gjithë kohën me të?» pyeti Sara. «Sepse ai është shumë i vogël», tha mamaja, «dhe s'di të bëjë asgjë vetë. As të hajë, as të lahet, as të kthehet në shtrat. Edhe për ty kam bërë të njëjtën gjë, kur ishe sa ai. Të kam mbajtur në krahë net të tëra. Të kam kënduar e të kam tundur. Ti s'e mban mend, por unë po.»$s$,
    $s$Sara u mendua. «Dhe unë qaja kështu fort?» «Edhe më fort!» qeshi mamaja. «Gjyshja thoshte që të dëgjonin deri në fund të rrugës.» Sara qeshi edhe ajo, me lotët ende në faqe. Pastaj mamaja i tha: «A e di çfarë? Lumi ka nevojë për ty. Ka nevojë për një motër të madhe, që t'i tregojë si është bota. Unë s'mund ta bëj këtë si ti.»$s$,
    $s$Atë natë, Lumi filloi të qante, si gjithmonë. Mamaja ishte në banjë, babai ishte në kuzhinë. Sara shkoi ngadalë te djepi i Lumit dhe e shikoi. Ishte i kuq në fytyrë, me grushtet që i lëviznin në ajër. Sara nuk e dinte çfarë të bënte. Pastaj kujtoi ninullën që i këndonte mamaja asaj, dhe filloi ta këndonte me zë të ulët: «Nina, nina, bir i nënës...»$s$,
    $s$Lumi pushoi së qari. Hapi sytë, të errët e të mëdhenj, dhe e shikoi Sarën. Pastaj, me grushtin e tij të vogël, i kapi gishtin. E kapi aq fort, sa Sara u habit. Dora e tij ishte e vogël, e ngrohtë, me thonj si kokrra orizi. Dhe s'ia lëshonte gishtin. Sara vazhdoi të këndonte, dhe Lumi mbylli sytë, me gishtin e saj ende në grusht.$s$,
    $s$Kur mamaja dhe babai erdhën, i gjetën të dy kështu: Sarën në gjunjë pranë djepit, duke kënduar, dhe Lumin që flinte, i kapur pas gishtit të motrës. Mamaja i vuri dorën babait në krah, dhe asnjëri s'foli, që të mos e prishnin atë çast.$s$,
    $s$Që nga ajo natë, Sara kishte një detyrë të veçantë. Ishte ajo që i këndonte Lumit kur qante. Ishte ajo që i tregonte lodrat me ngjyra. Ishte ajo që e bënte të qeshte, me fytyra qesharake, kur Lumi mësoi të qeshte. Dhe kur Lumi tha fjalën e tij të parë, nuk tha «mama» e as «baba». Tha «Sa», që ishte gjysma e emrit të motrës së tij.$s$,
    $s$Ndonjëherë, Sara ende ndjente pak xhelozi, kur të gjithë flisnin vetëm për Lumin. Por atëherë kujtonte zemrën e mamasë, që rritet në vend që të ndahet. Dhe kujtonte dorën e vogël të Lumit rreth gishtit të saj. Dhe e dinte që në botë kishte dikë që e donte, jo si mamaja, jo si babai, por në një mënyrë krejt të veçantë: si vëllai i vogël do motrën e madhe.$s$
  ]::text[],
  array['emotions']::text[], 0, 84, 11, null,
  $s$<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 160 120"><defs><linearGradient id="gvellaiivogel" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#F0E0CE"/><stop offset="1" stop-color="#F8EEE3"/></linearGradient></defs><rect x="0" y="0" width="160" height="120" fill="url(#gvellaiivogel)"/><rect x="14" y="14" width="34" height="40" rx="3" fill="#2E5566"/><path d="M24 23Q24 26 27 26Q24 26 24 29Q24 26 21 26Q24 26 24 23Z" fill="#F3EBD9"/><circle cx="38" cy="24" r="5" fill="#F3EBD9"/><path d="M31 14V54M14 34H48" fill="none" stroke="#F0E0CE" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"/><rect x="124" y="22" width="18" height="14" rx="1.5" fill="#E7D2BC"/><rect x="127" y="25" width="12" height="8" rx="1" fill="#A6CDB4"/><rect x="0" y="92" width="160" height="28" rx="0" fill="#DCC3A8"/><ellipse cx="80" cy="104" rx="50" ry="8" fill="#E7D2BC"/><ellipse cx="80" cy="98" rx="30" ry="3" fill="#000000" opacity="0.08"/><g transform="translate(43 35) scale(1.15)"><path d="M32 56Q4 36 8 20Q12 8 24 10Q30 12 32 18Q34 12 40 10Q52 8 56 20Q60 36 32 56Z" fill="#E58C8A"/><path d="M18 18Q22 14 26 16" fill="#FFFFFF" opacity="0.5"/><path d="M18 18Q22 14 26 16" fill="none" stroke="#FFFFFF" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/></g></svg>$s$,
  'published', true, 620, 'editor'
